-- AS AULAS DAS CAMPANHAS (26/11/2026).
--
-- As 16 campanhas foram escritas por inteiro em 27/10 (docs/campanhas/conteudo),
-- mas o banco ficou com os modelos antigos, de 2 a 4 acoes, e 11 deles mandavam
-- "ler a aula" com o texto vazio. Aqui entram os modelos completos das 15 da
-- vitrine: cada aula com o seu texto, os dias de cada acao na fase, o checklist
-- e as repeticoes iguais aos dias (a fase so fecha quando cada acao cumpre as dela).
-- Voz e Presenca e Criatividade em Sprint, fora da vitrine, ganham so o texto
-- da aula que faltava.
--
-- Preco, capa, tags e o resto do modelo ficam como estao. Quem ja instalou uma
-- campanha segue com as acoes que tem: o modelo so vale para a proxima instalacao.
--
-- Gerado por scripts/campanhas-md.mjs a partir dos MDs. Para mudar uma aula,
-- mude o MD e gere de novo. Pode ser rodado de novo sem estrago.

begin;

-- Sono de Elite (01-sono-de-elite.md)
update public.codex_catalog set
  title = 'Sono de Elite',
  description = 'Uma semana para acordar menos cansado, mexendo em duas coisas: a luz da noite e o horário de acordar.',
  duration_days = 7,
  template = template || jsonb_build_object(
    'title', 'Sono de Elite',
    'description', 'Uma semana para acordar menos cansado, mexendo em duas coisas: a luz da noite e o horário de acordar.',
    'durationDays', 7,
    'levels', $modelo$[{"level":1,"title":"Fase 1: A semana do sono","description":"Duas mudanças pequenas, todos os dias, e o porquê delas.","actions":[{"icon":"📘","name":"Por que você acorda cansado","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1230,"briefing":"Muita gente dorme oito horas e acorda como se tivesse dormido quatro. Quase sempre não é falta de sono. É o sono acontecendo do jeito errado.\n\nDurante a noite o corpo passa por ciclos de mais ou menos 90 minutos, indo do sono leve ao profundo e voltando. Ser acordado no meio do sono profundo é o que deixa aquela sensação de peso que demora horas para passar. Por isso uma noite de 7 horas pode render mais que uma de 9.\n[[page]]\nO relógio do corpo gosta de repetição. Ele aprende a que horas você costuma acordar e começa a preparar o corpo antes: a temperatura sobe, os hormônios do despertar aparecem, e você acorda quase sozinho.\n\nQuando o horário de acordar muda todo dia — cedo na semana, tarde no sábado —, o relógio nunca acerta. É como viver de fuso trocado sem viajar.\n[[page]]\nO outro lado é a noite. O sono profundo precisa de duas coisas que a vida moderna atrapalha: escuro e calma. Luz forte e tela na mão dizem ao cérebro que ainda é dia, e ele adia a hora de desligar.\n\nPor isso esta semana mexe em só duas coisas: o horário fixo de acordar, para o relógio do corpo aprender, e as telas longe da cama, para a noite ficar noite.\n[[page]]\nNão é preciso suplemento, aplicativo de sono ou rotina perfeita. A maioria das pessoas melhora tirando o que atrapalha, não acrescentando coisas.\n\nNos próximos dias você vai entender cada uma dessas mudanças e senti-las no corpo. O efeito costuma aparecer a partir do terceiro ou quarto dia."},{"icon":"📵","name":"Telas fora do quarto","description":"45 minutos antes de deitar, o celular vai carregar fora do quarto. Use o tempo para algo sem tela.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1320,"preFlight":["Celular carregando fora do quarto","Luz do quarto mais baixa","Despertador que não seja o celular (ou o celular longe da cama)"]},{"icon":"⏰","name":"Acordar no mesmo horário","description":"Levante no mesmo horário todos os dias, inclusive no fim de semana. Abra a janela ou acenda a luz logo ao acordar.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"preFlight":["Levantei no horário combinado","Luz do dia ou luz acesa nos primeiros minutos"]},{"icon":"💡","name":"A luz da noite","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1230,"briefing":"Quando escurece, o corpo começa a produzir melatonina, o sinal químico de que a noite chegou. Ela não é um sonífero: é um aviso. E esse aviso é muito sensível à luz.\n\nLuz forte à noite — teto branco, tela no rosto — diz ao cérebro que ainda é dia. A melatonina atrasa, o sono atrasa junto, e o despertador continua tocando na mesma hora.\n[[page]]\nA tela tem um segundo problema, talvez maior que a luz: ela mantém a cabeça ligada. Um vídeo puxa o próximo, uma mensagem pede resposta, uma notícia preocupa. O corpo deita, mas a mente continua no dia.\n\nPor isso o modo noturno ajuda pouco. Ele reduz a luz azul, mas não tira o celular da mão.\n[[page]]\nO que funciona é simples:\n\n— Nas últimas horas do dia, prefira luz baixa e amarelada.\n— Deixe a última meia hora sem tela: banho, leitura em papel, arrumar a roupa de amanhã, conversar.\n— Quarto escuro e mais para fresco. O corpo precisa baixar a temperatura para entrar no sono profundo.\n\nSe nos primeiros dias você sentir falta do celular, é normal. É justamente esse hábito que está mudando."},{"icon":"☕","name":"Café, álcool e horário","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1230,"briefing":"O café não dá energia: ele esconde o cansaço. Durante o dia o cérebro acumula uma substância que dá vontade de dormir, e a cafeína tapa os sensores dela.\n\nO problema é o tempo. Metade da cafeína de um café ainda está no corpo umas cinco ou seis horas depois. O café das quatro da tarde ainda está agindo quando você deita.\n[[page]]\nO álcool engana de outro jeito. Ele dá sono rápido e por isso parece ajudar. Mas, conforme o corpo o processa, o sono da segunda metade da noite fica raso e picado. Você dorme, mas descansa menos.\n\nJantar muito pesado perto de deitar faz algo parecido: o corpo fica ocupado digerindo quando deveria estar se recuperando.\n[[page]]\nTrês ajustes que costumam bastar:\n\n— Último café até o começo da tarde.\n— Álcool longe da hora de dormir, e não como \"remédio\" para pegar no sono.\n— Última refeição grande umas duas ou três horas antes de deitar.\n\nSe mesmo assim o sono continuar ruim por semanas — dificuldade de dormir, acordar várias vezes, ronco forte, cansaço que não passa —, vale procurar um médico. Esta campanha ajuda nos hábitos, não substitui uma avaliação."},{"icon":"🌙","name":"Como dormi esta semana","description":"Na anotação desta ocorrência, escreva em uma linha como você acordou nesta semana comparado com antes. Repare no que mudou e no que ainda atrapalha.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260,"preFlight":["Acordei melhor, igual ou pior que antes?","Qual dos dois hábitos foi mais fácil?","Qual vou manter na semana que vem?"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c01';

-- Detox Digital (02-detox-digital.md)
update public.codex_catalog set
  title = 'Detox Digital',
  description = 'Uma semana para tirar o celular do comando: menos notificação, mais tempo de verdade.',
  duration_days = 7,
  template = template || jsonb_build_object(
    'title', 'Detox Digital',
    'description', 'Uma semana para tirar o celular do comando: menos notificação, mais tempo de verdade.',
    'durationDays', 7,
    'levels', $modelo$[{"level":1,"title":"Fase 1: A semana sem coleira","description":"Arrumar o celular uma vez e treinar um tempo sem ele todo dia.","actions":[{"icon":"📘","name":"O que o scroll faz com sua atenção","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"O feed infinito foi desenhado para não ter fim. Não existe a última página, então não existe o momento natural de parar. Quem decide a hora de largar é você, contra um sistema feito para que você não largue.\n\nO que prende é a recompensa imprevisível. A maioria dos posts é morna, mas de vez em quando aparece um que diverte, choca ou interessa muito. Como não dá para saber quando vem o próximo bom, o dedo continua descendo. É o mesmo mecanismo das máquinas de caça-níquel.\n[[page]]\nO custo não aparece na hora. Aparece no fim do dia, quando você soma: meia hora aqui, vinte minutos ali, e o tempo para o que você queria fazer simplesmente não existiu.\n\nAparece também na atenção. Depois de muito estímulo rápido, ler duas páginas seguidas ou ficar numa conversa sem pegar o celular começa a parecer difícil. Não é falta de caráter: é treino. O cérebro fica bom no que faz muito.\n[[page]]\nA boa notícia é que o treino funciona nos dois sentidos. Esta semana você não vai largar o celular para sempre. Vai fazer duas coisas: arrumar o aparelho para ele chamar menos, e passar um tempo por dia sem ele, começando pequeno.\n\nHoje é dia de faxina: tirar do celular o poder de te chamar a cada minuto."},{"icon":"🔕","name":"Faxina de notificações","description":"Uma vez só: deixe o celular chamar você apenas para o que é de gente. O resto você vê quando decidir abrir.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Desligar as notificações de redes sociais e de jogos","Deixar ligadas só as de pessoas (mensagens, ligações) e as essenciais","Tirar as redes da primeira tela do celular","Silenciar os grupos que não são urgentes"]},{"icon":"📵","name":"Janela sem tela (30 min)","description":"30 minutos sem nenhuma tela. O celular fica em outro cômodo ou numa gaveta. Faça qualquer coisa que não tenha tela.","duration":30,"difficulty":2,"actionType":"Ação Recorrente","repetitions":2,"dias":[2,3],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Celular fora de alcance","Algo para fazer sem tela (ler, cozinhar, caminhar, arrumar, conversar)"]},{"icon":"📘","name":"O custo escondido de cada interrupção","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Uma notificação dura dois segundos. O estrago dura bem mais.\n\nQuando você para o que está fazendo para olhar o celular, uma parte da sua atenção fica presa lá, mesmo depois de voltar. Pesquisadores chamam isso de resíduo de atenção: você volta para a tarefa, mas ainda pensando na mensagem, no vídeo, no que vai responder.\n[[page]]\nVoltar ao ponto em que estava leva tempo. Em trabalho que exige concentração, cada interrupção pode custar vários minutos de retomada. Somando as interrupções de um dia, sobra pouco tempo de cabeça inteira em alguma coisa.\n\nE quanto mais o dia é picado, mais cansado você termina, mesmo sem ter feito muito. Alternar o tempo todo cansa mais do que fazer uma coisa só.\n[[page]]\nPor isso a faxina de notificações vale mais do que parece. Cada alerta desligado é uma interrupção a menos por dia, todos os dias.\n\nA partir de hoje a janela sem tela sobe para 45 minutos. Repare no que acontece com a vontade de pegar o celular: ela vem, aperta um pouco e passa. Ela sempre passa."},{"icon":"📵","name":"Janela sem tela (45 min)","description":"Agora são 45 minutos sem nenhuma tela. Mesmo jeito: celular longe e algo para fazer com as mãos ou com alguém.","duration":45,"difficulty":2,"actionType":"Ação Recorrente","repetitions":2,"dias":[4,5],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Celular fora de alcance","Algo para fazer sem tela"]},{"icon":"📵","name":"Janela sem tela (60 min)","description":"Uma hora inteira sem tela, o maior tempo da semana. Se der, saia de casa: caminhe, visite alguém, faça algo diferente.","duration":60,"difficulty":3,"actionType":"Ação Recorrente","repetitions":2,"dias":[6,7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Celular fora de alcance","Uma atividade escolhida antes de começar"]},{"icon":"🌿","name":"O que fiz com o tempo que sobrou","description":"Na anotação desta ocorrência, escreva em uma linha o que você fez nas janelas sem tela e o que quer manter.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1290,"preFlight":["O que fiz de melhor sem tela","Quanto tempo por dia quero manter","Alguma notificação que voltei a ligar? Por quê?"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c06';

-- Controle de Impulsos (03-controle-de-impulsos.md)
update public.codex_catalog set
  title = 'Controle de Impulsos',
  description = 'Cinco dias para separar o que você quer do que você só quis por um minuto.',
  duration_days = 5,
  template = template || jsonb_build_object(
    'title', 'Controle de Impulsos',
    'description', 'Cinco dias para separar o que você quer do que você só quis por um minuto.',
    'durationDays', 5,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Cinco dias de freio","description":"Entender o impulso e colocar um intervalo entre a vontade e a compra.","actions":[{"icon":"📘","name":"O impulso tem prazo de validade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"A vontade de comprar algo que você não planejava costuma ser forte e curta. Ela sobe rápido, ao ver a oferta, o anúncio ou o produto na mão de alguém, e desce sozinha se você der tempo a ela.\n\nO problema é que comprar ficou mais rápido que a vontade passar. Um toque, um cartão salvo, e pronto. Não sobra nenhum intervalo entre querer e ter.\n[[page]]\nA regra mais simples para devolver esse intervalo é a das 48 horas: tudo o que não estava planejado vai para uma lista e espera dois dias. Se depois disso ainda fizer sentido, você compra sem culpa.\n\nNa maioria das vezes, dois dias depois a coisa já não parece tão necessária. E quando parece, a compra fica melhor: você pesquisou, comparou e decidiu de cabeça fria.\n[[page]]\nIsso não é sobre nunca gastar. É sobre gastar no que você escolheu, e não no que escolheram por você num momento de distração.\n\nHoje você monta essa lista. E toda noite, por cinco dias, vai registrar em uma linha se a vontade apareceu e o que fez com ela."},{"icon":"📝","name":"Montar a lista de espera","description":"Escolha um lugar fixo para a lista de espera (nota do celular, papel na carteira). Tudo o que não estava planejado vai para lá e espera 48 horas.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Lista criada num lugar fácil de abrir","Remover o cartão salvo de pelo menos um app de compras","Desligar notificações de promoção"]},{"icon":"🔎","name":"Registro da noite","description":"Na anotação desta ocorrência, uma linha: hoje deu vontade de comprar algo fora do plano? O que fiz?","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":5,"dias":[1,2,3,4,5],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260,"preFlight":["Teve vontade de compra fora do plano?","Foi para a lista ou foi comprado?","O que estava sentindo na hora?"]},{"icon":"📘","name":"Seus gatilhos","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"O impulso quase nunca aparece do nada. Ele costuma vir em momentos parecidos, e conhecer os seus é meio caminho andado.\n\nOs mais comuns: cansaço no fim do dia, tédio, um dia ruim que pede uma recompensa, e o tempo rolando o celular, onde os anúncios são feitos sob medida para você.\n[[page]]\nOlhe para os seus registros desde o primeiro dia. Em que horário a vontade apareceu? Onde você estava? Como estava se sentindo?\n\nSe o padrão for \"à noite, cansado, no celular\", a solução não é força de vontade. É mudar o ambiente: menos apps de compra no celular, cartão menos à mão, outra coisa para fazer nesse horário.\n[[page]]\nComprar para se sentir melhor funciona por alguns minutos. Vale perguntar o que de fato ajudaria naquele momento: descansar, conversar com alguém, sair para andar.\n\nNos próximos dois dias, quando a vontade vier, tente dar nome a ela: é necessidade, é tédio ou é cansaço?"},{"icon":"📘","name":"Quantas horas de trabalho custa","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Preço em reais engana, porque dinheiro na tela não parece suado. Uma conta simples muda a sensação: quanto você ganha por hora de trabalho?\n\nDivida o que você recebe por mês pelas horas que trabalha no mês. O número que sair é o valor da sua hora.\n[[page]]\nAgora olhe para qualquer coisa que você quer comprar e faça a pergunta: quantas horas de trabalho isso custa? Aquele item de 300 reais pode ser um dia inteiro de trabalho.\n\nÀs vezes vale. Muitas vezes não. Mas, olhando assim, a decisão passa a ser sua, e não da oferta."},{"icon":"🧾","name":"Revisar a lista de espera","description":"Abra a lista de espera e decida item por item: ainda faz sentido? Na anotação, escreva o que decidiu e quanto deixou de gastar.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1290,"preFlight":["Ler cada item da lista","Riscar o que perdeu a graça","Para o que ficou, conferir as horas de trabalho que custa"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c04';

-- Presença Real (04-presenca-real.md)
update public.codex_catalog set
  title = 'Presença Real',
  description = 'Uma semana de conversas com o celular longe e a atenção perto.',
  duration_days = 7,
  template = template || jsonb_build_object(
    'title', 'Presença Real',
    'description', 'Uma semana de conversas com o celular longe e a atenção perto.',
    'durationDays', 7,
    'levels', $modelo$[{"level":1,"title":"Fase 1: A semana presente","description":"Uma conversa por dia de verdade, sem tela no meio.","actions":[{"icon":"📘","name":"Estar junto não é estar presente","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1110,"briefing":"Dá para passar uma noite inteira ao lado de alguém sem ter estado com essa pessoa. Cada um no seu celular, uma frase de vez em quando, e a sensação depois de que faltou alguma coisa.\n\nEstudos sobre conversa mostram algo curioso: só ter um celular em cima da mesa, mesmo virado para baixo, já deixa a conversa mais rasa. As pessoas evitam assuntos importantes, porque sabem que podem ser interrompidas a qualquer momento.\n[[page]]\nPresença não exige horas. Exige que, naquele tempo, a outra pessoa seja a coisa mais importante na sua frente.\n\nEsta semana o exercício é pequeno: uma conversa por dia com o celular fora de vista. Pode ser no jantar, num café, numa ligação. O que importa é a atenção inteira, mesmo que por quinze minutos."},{"icon":"🤝","name":"Conversa sem celular","description":"Tenha uma conversa com alguém com o celular fora de vista. Faça pelo menos uma pergunta de volta sobre o que a pessoa contou.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1170,"preFlight":["Celular em outro cômodo, na bolsa ou no bolso (não na mesa)","Uma pergunta de volta sobre o que a pessoa disse","Deixar a pessoa terminar antes de responder"]},{"icon":"📘","name":"Escutar para entender","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1110,"briefing":"Na maioria das conversas a gente não escuta: espera a vez de falar. Enquanto o outro conta, a cabeça já está montando a resposta, a história parecida, o conselho.\n\nEscutar de verdade é outra coisa. É tentar entender o que a pessoa está dizendo e o que ela está sentindo enquanto diz.\n[[page]]\nTrês coisas simples mudam muito:\n\n— Perguntar de volta: \"e como foi isso pra você?\", \"o que aconteceu depois?\".\n— Resumir com as suas palavras: \"então você ficou chateado porque…\". A pessoa se sente ouvida, e você confere se entendeu.\n— Segurar o conselho até ele ser pedido. Muitas vezes a pessoa só quer ser ouvida.\n\nNas conversas dos próximos dias, tente uma dessas por vez."},{"icon":"💌","name":"Uma mensagem sincera","description":"Mande para alguém que importa uma mensagem dizendo algo verdadeiro: um agradecimento, uma lembrança, por que essa pessoa é importante. Sem esperar nada de volta.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1230,"preFlight":["Escolher a pessoa","Dizer algo específico, não genérico","Enviar sem pedir nada em troca"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c05';

-- Mente sem Armadilhas (05-mente-sem-armadilhas.md)
update public.codex_catalog set
  title = 'Mente sem Armadilhas',
  description = 'Cinco atalhos do pensamento que enganam todo mundo, e como pegar cada um no seu dia.',
  duration_days = 5,
  template = template || jsonb_build_object(
    'title', 'Mente sem Armadilhas',
    'description', 'Cinco atalhos do pensamento que enganam todo mundo, e como pegar cada um no seu dia.',
    'durationDays', 5,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Cinco armadilhas","description":"Um viés por dia, e a prática de notar quando ele aparece.","actions":[{"icon":"🧠","name":"Viés de confirmação","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":480,"briefing":"O cérebro não procura a verdade: procura confirmação. Quando você já acredita em algo, tende a notar o que prova que está certo e a passar batido pelo que mostra o contrário.\n\nÉ por isso que duas pessoas leem a mesma notícia e saem com certezas opostas. Cada uma lembrou da parte que combinava com o que já pensava.\n[[page]]\nIsso acontece com assuntos grandes e com coisas pequenas: a opinião sobre um colega, a certeza de que \"isso nunca dá certo comigo\", a escolha de um produto.\n\nUm antídoto simples: diante de uma opinião forte, pergunte \"o que me faria mudar de ideia?\". Se a resposta for \"nada\", provavelmente é o viés falando.\n\nHoje, repare num momento em que você só procurou o que já concordava."},{"icon":"🧠","name":"Custo afundado","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[2],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":480,"briefing":"Você já ficou até o fim de um filme ruim porque pagou o ingresso? Ou continuou num projeto que não fazia mais sentido porque já tinha investido meses nele?\n\nIsso é o custo afundado: o que você já gastou — tempo, dinheiro, esforço — pesa na decisão de continuar, mesmo que não volte de jeito nenhum.\n[[page]]\nO tempo e o dinheiro já foram, você continuando ou não. A única pergunta que importa é: daqui para frente, isso vale a pena?\n\nA frase-teste: \"se eu estivesse começando agora, do zero, eu escolheria isso?\". Se não, talvez seja hora de parar, por mais que doa.\n\nHoje, procure algo que você só continua por já ter começado."},{"icon":"🧠","name":"Ancoragem","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":480,"briefing":"O primeiro número que você vê vira uma âncora, e todos os outros são julgados a partir dele.\n\nA camisa \"de 200 por 99\" parece barata porque o 200 veio primeiro. Numa negociação, quem fala o primeiro valor puxa o resto da conversa para perto dele. Até uma estimativa de tempo muda conforme o número que alguém disse antes.\n[[page]]\nA âncora funciona mesmo quando é absurda ou sem relação nenhuma com o assunto. O cérebro usa o que tem à mão como ponto de partida.\n\nPara se defender: antes de olhar o preço \"de\", decida quanto aquilo vale para você. Numa negociação, pense no seu número antes de ouvir o do outro.\n\nHoje, repare num preço, prazo ou número que mudou a sua impressão de algo."},{"icon":"🧠","name":"Viés da negatividade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":480,"briefing":"Dez elogios e uma crítica: qual você lembra à noite? Para quase todo mundo, a crítica.\n\nO cérebro dá mais peso ao que é ruim do que ao que é bom. Faz sentido na história da espécie: perceber um perigo era mais urgente que perceber uma coisa boa. Hoje, isso faz um dia bom parecer ruim por causa de um único momento.\n[[page]]\nO resultado é uma visão torta: das pessoas, do próprio progresso, do mundo. Você vê mais o que falta do que o que já conquistou.\n\nUm ajuste simples: no fim do dia, além do que deu errado, anote três coisas que deram certo, mesmo que pequenas. Não é fingir que está tudo bem. É equilibrar a balança.\n\nHoje, repare num momento em que algo ruim apagou várias coisas boas."},{"icon":"🧠","name":"Efeito manada","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":480,"briefing":"Se todo mundo está fazendo, deve estar certo. É assim que o cérebro economiza energia: em vez de pensar sozinho, segue o grupo.\n\nMuitas vezes funciona. Mas é o mesmo mecanismo que enche um restaurante só porque está cheio, faz todo mundo comprar a mesma moda e deixa as pessoas caladas numa reunião em que todos discordam em silêncio.\n[[page]]\nO efeito manada fica mais forte quando você está inseguro: num assunto que não domina, num lugar novo, numa decisão difícil.\n\nA pergunta que ajuda: \"eu faria isso se ninguém mais estivesse fazendo?\". Seguir o grupo pode ser uma ótima escolha, desde que seja uma escolha.\n\nHoje, repare em algo que você fez, ou quase fez, só porque os outros estavam fazendo."},{"icon":"🔍","name":"Caçar o viés do dia","description":"Na anotação desta ocorrência, escreva uma vez em que o viés da aula de hoje apareceu, em você ou em alguém em volta.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":5,"dias":[1,2,3,4,5],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260,"preFlight":["Qual foi a situação","Como o viés apareceu","O que eu faria diferente"]},{"icon":"🪞","name":"Qual mais me pega","description":"Releia as anotações da semana e escreva qual das cinco armadilhas mais aparece na sua vida e uma regra simples para se defender dela.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1290,"preFlight":["Reler as cinco anotações","Escolher a armadilha mais frequente","Escrever uma regra para ela"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c02';

-- Expressão Criativa (06-expressao-criativa.md)
update public.codex_catalog set
  title = 'Expressão Criativa',
  description = 'Duas semanas para sair do "um dia eu faço" e terminar uma peça sua: desenho, texto, música, foto, o que for.',
  duration_days = 14,
  template = template || jsonb_build_object(
    'title', 'Expressão Criativa',
    'description', 'Duas semanas para sair do "um dia eu faço" e terminar uma peça sua: desenho, texto, música, foto, o que for.',
    'durationDays', 14,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Volume","description":"Produzir todo dia sem julgar. Quantidade primeiro.","actions":[{"icon":"📘","name":"O gosto chega antes da mão","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Quem começa algo criativo quase sempre passa pela mesma frustração: você sabe reconhecer o que é bom, mas o que você faz ainda não é. O gosto chegou antes da mão.\n\nIsso não é sinal de falta de talento. É sinal de que o seu gosto é bom, e é justamente ele que vai te puxar para cima.\n[[page]]\nA única coisa que fecha essa distância é volume. Fazer muito, mesmo sem ficar bom. Cada tentativa ruim ensina a mão um pouco mais.\n\nQuem trava esperando fazer algo bom logo de cara para de produzir. E quem para de produzir nunca fica bom.\n[[page]]\nEsta semana a regra é uma só: produzir todos os dias, sem apagar, sem refazer, sem mostrar a ninguém. Desenho, texto, música, foto, receita: escolha um e faça.\n\nO objetivo da primeira semana não é qualidade. É quantidade."},{"icon":"🎨","name":"Produção sem apagar","description":"30 minutos produzindo na sua forma de expressão. Proibido apagar ou recomeçar: o que sair, fica. Guarde tudo numa pasta só.","duration":30,"difficulty":2,"actionType":"Ação Recorrente","repetitions":6,"dias":[1,2,3,4,5,6],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1140,"preFlight":["Material separado antes de começar","Celular no silencioso","Guardar o que saiu, mesmo que ruim"]},{"icon":"📘","name":"Limites criam","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"A folha em branco assusta porque tem possibilidades demais. Sem limite nenhum, o cérebro não sabe por onde começar.\n\nPor isso limites ajudam a criar. Um poema com só cinco linhas. Um desenho usando só três cores. Uma música com dois acordes. Uma foto por dia, só de coisas vermelhas.\n[[page]]\nO limite tira a pressão de fazer \"a obra\" e transforma a criação num jogo com regras. E dentro das regras aparece a criatividade, procurando saídas.\n\nNos próximos dias, antes de começar, escolha um limite para aquela sessão. Escreva qual foi na anotação."},{"icon":"📘","name":"Rotina vence inspiração","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Esperar a inspiração é a forma mais comum de não criar nada. Ela costuma aparecer no meio do trabalho, não antes dele.\n\nMuitos artistas e escritores repetem a mesma coisa: eles trabalham num horário fixo, todos os dias, com vontade ou sem. A inspiração aprende o caminho e passa a aparecer na hora marcada.\n[[page]]\nVocê já está fazendo isso há cinco dias. Repare se ficou mais fácil começar. Normalmente fica: o começo deixa de ser uma decisão e vira hábito.\n\nNa semana que vem você vai escolher uma das coisas que fez e levá-la até o fim. Comece a pensar em qual delas te deu mais vontade de continuar."},{"icon":"⭐","name":"Escolher a melhor da semana","description":"Olhe tudo o que produziu na semana e escolha uma peça para terminar na próxima fase. Na anotação, diga qual e por quê.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1140,"preFlight":["Rever tudo o que fiz","Escolher uma peça","Anotar o que falta para ela ficar pronta"]}]},{"level":2,"title":"Fase 2: Uma peça terminada","description":"Escolher a melhor coisa e levar até o fim.","actions":[{"icon":"📘","name":"Terminar é uma habilidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Começar é divertido. Terminar é trabalho. Quase todo mundo tem gavetas cheias de coisas começadas e nada pronto.\n\nTerminar é uma habilidade separada de criar: decidir que está bom o suficiente, resolver os detalhes chatos, aceitar que não ficou perfeito.\n[[page]]\nUma regra que ajuda: defina agora o que é \"pronto\". Um texto revisado e com título. Um desenho finalizado e escaneado. Uma música gravada do começo ao fim. Sem essa definição, a peça nunca termina, porque sempre dá para mexer mais.\n\nEscreva na anotação o que é \"pronto\" para a sua peça. Essa é a sua linha de chegada da semana."},{"icon":"🛠️","name":"Refinar a peça escolhida","description":"30 minutos trabalhando só na peça escolhida, em direção ao \"pronto\" que você definiu.","duration":30,"difficulty":2,"actionType":"Ação Recorrente","repetitions":6,"dias":[1,2,3,4,5,6],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1140,"preFlight":["Saber o que vou resolver hoje","Trabalhar só nesta peça","Anotar o que falta"]},{"icon":"📘","name":"Mostrar sem pedir aprovação","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Mostrar o que você fez dá medo porque parece que você está pedindo uma nota. Não precisa ser assim.\n\nMostrar é fechar o ciclo. A peça sai da sua cabeça e passa a existir para outra pessoa. É isso que transforma um passatempo em expressão.\n[[page]]\nEscolha uma pessoa de confiança ou um lugar onde se sinta à vontade. Mostre dizendo o que você quis fazer, não pedindo \"ficou bom?\".\n\nO que vier de volta é informação, não sentença. E se não vier nada, a peça continua existindo, terminada. Isso já é muito."},{"icon":"🏁","name":"Peça pronta e mostrada","description":"Dê os últimos retoques, declare a peça pronta e mostre para uma pessoa ou publique. Na anotação, conte como foi.","duration":30,"difficulty":3,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"high"},"scheduledStartTime":1140,"preFlight":["A peça bate com o \"pronto\" que defini","Mostrei para alguém ou publiquei","Anotei o que aprendi fazendo"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42d10';

-- Círculo Forte (07-circulo-forte.md)
update public.codex_catalog set
  title = 'Círculo Forte',
  description = 'Duas semanas para cuidar das pessoas que somam na sua vida, de um jeito que não é forçado.',
  duration_days = 14,
  template = template || jsonb_build_object(
    'title', 'Círculo Forte',
    'description', 'Duas semanas para cuidar das pessoas que somam na sua vida, de um jeito que não é forçado.',
    'durationDays', 14,
    'levels', $modelo$[{"level":1,"title":"Fase 1: O mapa","description":"Saber quem está perto e falar com uma pessoa por dia.","actions":[{"icon":"📘","name":"Você vira quem está perto","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Hábitos, humor e até ambições passam de pessoa para pessoa. Quem convive com gente que lê, lê mais. Quem anda com gente que reclama de tudo, reclama mais.\n\nNão é que você precise escolher amigos como quem escolhe investimento. Mas vale saber quem está perto e cuidar de quem faz bem.\n[[page]]\nO problema é que relação boa, quando ninguém cuida, esfria. Não por briga: por falta de contato. A vida corre, e um \"a gente se fala\" vira um ano sem conversa.\n\nHoje você vai listar 10 pessoas que somam: que te fazem bem, te puxam para cima, que você admira ou com quem sente falta de conversar. Família, amigos, colegas, antigos professores, tanto faz."},{"icon":"🗺️","name":"Listar 10 pessoas que somam","description":"Escreva na anotação 10 pessoas que fazem bem para você. Ao lado de cada uma, quando foi a última conversa de verdade.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1140,"preFlight":["10 nomes","Última conversa de cada um (mais ou menos)","Marcar as 3 que estão mais distantes"]},{"icon":"💬","name":"Um contato intencional","description":"Fale com uma pessoa da sua lista com um motivo de verdade: lembrei de você por causa de…, vi isso e pensei em você, como foi aquilo que você contou? Nada de \"oi sumido\".","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":6,"dias":[2,3,4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1170,"preFlight":["Escolher a pessoa do dia","Mensagem com motivo concreto","Responder com atenção se ela responder"]},{"icon":"📘","name":"Laços fracos abrem portas","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Seus amigos mais próximos conhecem as mesmas pessoas e os mesmos assuntos que você. Os conhecidos — um ex-colega, alguém de um curso, um amigo de amigo — circulam em outros mundos.\n\nPor isso, quando se fala de oportunidade nova (emprego, ideia, indicação), ela costuma vir dos laços fracos, e não dos mais fortes. Eles trazem informação que você não teria de outro jeito.\n[[page]]\nLaço fraco não precisa de muito: uma mensagem de vez em quando, um parabéns sincero, uma indicação útil. É o tipo de contato que custa pouco e mantém a porta aberta.\n\nNos próximos contatos, inclua alguém que você conhece menos, mas com quem gostaria de manter a ligação."},{"icon":"📘","name":"Frequência vence intensidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"Uma viagem incrível com um amigo uma vez a cada cinco anos vale menos para a amizade do que um café por mês. Relação se constrói mais por repetição do que por grandes momentos.\n\nO contato pequeno e frequente diz \"você está na minha vida\". O encontro raro e enorme diz \"a gente era amigo\".\n[[page]]\nIsso tira um peso: você não precisa planejar nada grandioso para cuidar das pessoas. Precisa de constância.\n\nRepare nos contatos desta semana: quais conversas continuaram sozinhas? Essas são as relações que estão vivas e merecem um passo a mais."},{"icon":"🎯","name":"Escolher 2 pessoas para aprofundar","description":"Na anotação, escolha 2 pessoas da sua lista para a próxima fase: alguém para ajudar de alguma forma e alguém para encontrar pessoalmente.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1230,"preFlight":["Uma pessoa para oferecer algo","Uma pessoa para encontrar","Por que essas duas"]}]},{"level":2,"title":"Fase 2: Aprofundar","description":"Oferecer valor e transformar mensagens em encontros.","actions":[{"icon":"📘","name":"Oferecer antes de pedir","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"As relações mais fortes são as de mão dupla. E quase sempre começam com alguém oferecendo algo antes de precisar de qualquer coisa.\n\nOferecer não é dar presente. É ser útil: indicar alguém, mandar um artigo que resolve um problema da pessoa, lembrar de uma data importante, ajudar numa mudança.\n[[page]]\nO segredo é a atenção. Quem escuta sabe do que o outro precisa. Por isso o contato intencional da semana passada vale tanto: você sabe mais da vida das pessoas agora.\n\nEsta semana, todo dia, um gesto de valor para alguém da sua lista. Pequeno, concreto, sem pedir nada em troca."},{"icon":"🎁","name":"Um gesto de valor","description":"Faça algo útil para alguém da sua lista: uma indicação, uma ajuda, um conteúdo que resolve algo dela, um elogio específico. Sem pedir nada.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":6,"dias":[1,2,3,4,5,6],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1170,"preFlight":["Para quem foi","O que ofereci","Sem pedir nada em troca"]},{"icon":"📘","name":"Como marcar sem constranger","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"briefing":"\"Vamos marcar!\" é a frase mais dita e menos cumprida da amizade. O encontro não acontece porque ninguém propõe nada concreto.\n\nO jeito que funciona: propor dia, hora e lugar, simples e fácil de aceitar. \"Quinta, café às 19h perto do seu trabalho?\" é muito mais fácil de responder do que \"vamos marcar algo\".\n[[page]]\nSe a pessoa não puder, peça uma alternativa: \"qual dia é melhor pra você?\". E aceite um não sem drama: a porta continua aberta.\n\nEscolha hoje quando e onde vai propor o encontro com a pessoa que você escolheu."},{"icon":"☕","name":"Encontro feito","description":"Encontre pessoalmente uma das pessoas que você escolheu. Celular fora da mesa. Na anotação, escreva como foi.","duration":60,"difficulty":3,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"high"},"scheduledStartTime":1140,"preFlight":["Encontro proposto com dia, hora e lugar","Celular fora da mesa","Combinar o próximo, se fizer sentido"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42d08';

-- Estoicismo Aplicado (09-estoicismo-aplicado.md)
update public.codex_catalog set
  title = 'Estoicismo Aplicado',
  description = 'Duas semanas de filosofia prática: um princípio por dia, e depois a vida real como treino.',
  duration_days = 14,
  template = template || jsonb_build_object(
    'title', 'Estoicismo Aplicado',
    'description', 'Duas semanas de filosofia prática: um princípio por dia, e depois a vida real como treino.',
    'durationDays', 14,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Os princípios","description":"Sete ideias estoicas, uma por dia, e a revisão da noite.","actions":[{"icon":"🏛️","name":"O controle","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Existe uma linha que divide tudo na sua vida em dois lados.\n\nDe um lado: o que depende de você. Seus pensamentos, suas escolhas, suas respostas, seus esforços. Do outro lado: tudo o mais. O que as pessoas pensam de você, o resultado das suas decisões, o clima, o trânsito, a economia, o comportamento dos outros. Os estoicos chamavam essa divisão de dicotomia do controle — e consideravam a confusão entre os dois lados a principal fonte de sofrimento humano.\n[[page]]\nO problema não é que coisas ruins acontecem. É que gastamos energia tentando controlar o que não controlamos.\n\nVocê se preocupa com a opinião do seu chefe sobre uma apresentação que já foi entregue. Você rumina sobre uma conversa que já aconteceu. Você anseia por um resultado que depende de dez variáveis fora do seu alcance. Toda essa energia gasta no lado errado da linha não muda nada no mundo externo — só drena o que você tinha disponível para o que realmente depende de você.\n[[page]]\nIdentificar o lado da linha onde cada coisa está não é resignação. É precisão.\n\nQuando você para e pergunta \"isso depende de mim?\" antes de gastar energia em qualquer coisa, duas coisas acontecem. O que está fora do seu controle perde o poder de te paralisar — porque você conscientemente escolhe não investir ali. E o que está dentro do seu controle recebe atenção total — porque é o único lugar onde seu esforço produz resultado real.\n\nA prática não elimina o desconforto. Ela redireciona onde você coloca o peso."},{"icon":"🏛️","name":"A adversidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[2],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Os estoicos não acreditavam em evitar dificuldade. Acreditavam em usá-la.\n\nPara Marco Aurélio, Sêneca e Epicteto — três homens que viveram sob perseguição, exílio e escravidão — a adversidade não era o oposto do crescimento. Era o instrumento dele. O obstáculo não estava no caminho. O obstáculo era o caminho. Essa inversão não é otimismo forçado. É uma conclusão prática sobre como o caráter humano se desenvolve.\n[[page]]\nNinguém se torna resiliente em condições confortáveis.\n\nTolerância à frustração, capacidade de continuar sob pressão, clareza de valores quando tudo está difícil — essas qualidades não aparecem porque você as deseja. Aparecem porque foram testadas e você escolheu continuar. A adversidade é o único ambiente onde esse teste pode acontecer.\n[[page]]\nA pergunta estoica diante de qualquer dificuldade é sempre a mesma: o que isso me permite praticar?\n\nPaciência. Criatividade. Humildade. Persistência. Cada obstáculo específico convoca uma virtude específica.\n\nIsso não significa que dificuldade não dói. Significa que a dor pode ter direção."},{"icon":"🏛️","name":"O tempo","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Você age como se tivesse tempo sobrando. Os estoicos agiam como se não tivessem.\n\nSêneca escreveu que o problema não é termos pouco tempo — é desperdiçarmos muito do que temos. A vida é longa o suficiente para quase tudo que importa, se usada com intenção. O que a encurta não é o calendário. É a atenção dividida, o adiamento crônico e a ilusão de que o momento certo está sempre à frente.\n[[page]]\nA prática do memento mori — lembrar que você vai morrer — não foi criada para deprimir. Foi criada para calibrar.\n\nQuando você tem consciência real da finitude, as decisões sobre onde colocar atenção e energia mudam. O que você estava tolerando por preguiça se torna inaceitável. O que você estava adiando por medo se torna urgente.\n[[page]]\nO passado não existe mais. O futuro ainda não existe. O único lugar onde qualquer coisa real pode acontecer é o momento presente — e é exatamente o lugar onde a maioria das pessoas menos está.\n\nViver bem não é viver muito. É viver com presença no que está acontecendo agora."},{"icon":"🏛️","name":"A virtude","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Para os estoicos, virtude não era um conceito moral abstrato. Era uma habilidade prática.\n\nCoragem, justiça, temperança e sabedoria — as quatro virtudes do estoicismo — não eram qualidades que você tinha ou não tinha. Eram capacidades que se desenvolviam com prática, como um músculo se desenvolve com treino. Você não era corajoso ou covarde por natureza. Você praticava coragem ou evitava as situações que a exigiam.\n[[page]]\nA virtude era o único bem real porque era o único que não podia ser tirado de você.\n\nRiqueza, reputação, saúde, relacionamentos — tudo isso pode ser perdido por circunstâncias fora do seu controle. Sua forma de responder ao que acontece nunca pode ser tirada sem a sua permissão. É por isso que Epicteto, que foi escravo, escrevia sobre liberdade com mais autoridade que a maioria dos homens livres.\n\nPraticar virtude não é ser perfeito. É fazer a escolha certa uma vez a mais do que você teria feito ontem."},{"icon":"🏛️","name":"O julgamento","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Você não reage às coisas. Você reage à sua interpretação das coisas.\n\nEpicteto dizia que os homens não são perturbados pelos eventos, mas pelas opiniões que formam sobre eles. Um engarrafamento não é estressante — a ideia de que seu tempo está sendo desperdiçado é que produz o estresse. Uma crítica não é dolorosa — a interpretação de que ela ameaça sua imagem é que dói.\n[[page]]\nIsso tem uma implicação prática enorme: você pode mudar como se sente sem mudar o que acontece.\n\nNão por negação — os estoicos eram realistas. Mas por revisão do julgamento. Entre o que acontece e a sua resposta existe um espaço, pequeno mas real. Nesse espaço está a sua liberdade.\n[[page]]\nA pergunta que alarga esse espaço é simples: isso é tão grave quanto parece agora?\n\nNa maioria das vezes, a resposta honesta é não."},{"icon":"🏛️","name":"A comunidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[6],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Os estoicos acreditavam que o ser humano não existe isolado. Existe em relação.\n\nMarco Aurélio escrevia sobre a interdependência humana — a ideia de que cada pessoa é parte de algo maior, e que agir bem dentro disso não é bondade extra, é a função natural de quem entende onde está. Você foi formado por outros. Você será lembrado pelo que fez pelos outros.\n[[page]]\nMas comunidade estoica não é conformidade. É responsabilidade.\n\nFazer parte de um grupo não significa abrir mão dos próprios valores para agradar. Significa contribuir com o que você tem de melhor e manter seus princípios mesmo quando o grupo pressiona na direção oposta.\n\nA pergunta estoica sobre qualquer relação é: o que eu devo a essa pessoa como ser humano?"},{"icon":"🏛️","name":"O caráter","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Caráter não é o que você mostra quando está sendo observado. É o que você faz quando não está.\n\nOs estoicos tinham pouco interesse em reputação e muito interesse em caráter — porque reputação é o que os outros pensam de você, e caráter é o que você realmente é. A distância entre os dois é a medida da sua integridade.\n[[page]]\nCaráter se revela sob pressão, não sob conforto.\n\nÉ fácil ser generoso quando está sobrando. É fácil ser paciente quando nada testa sua paciência. O que conta é como você age cansado, com raiva, quando ninguém está olhando e quando a escolha certa é a mais difícil.\n\nAo final destes 7 dias, a pergunta não é o que você aprendeu sobre estoicismo. É o que você fez diferente por causa disso. A próxima semana é sobre isso."},{"icon":"🌙","name":"Revisão da noite","description":"Na anotação, três linhas: o que aconteceu hoje, como o princípio do dia se aplica e o que você faria diferente.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1290,"preFlight":["O que aconteceu (só os fatos)","Como o princípio de hoje ilumina isso","Uma ação concreta para amanhã"]}]},{"level":2,"title":"Fase 2: Na vida real","description":"Usar os princípios nas situações difíceis do dia.","actions":[{"icon":"🏛️","name":"Raiva e ofensa","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Sêneca escreveu um livro inteiro sobre a raiva. A conclusão dele: ela é uma loucura curta, que nos faz agir de um jeito de que nos arrependemos.\n\nA raiva nasce de um julgamento: \"isso não deveria ter acontecido comigo\", \"essa pessoa me desrespeitou\". O estoico não finge que não sente. Ele atrasa a resposta.\n[[page]]\nO conselho mais prático de Sêneca é a demora. Antes de responder com raiva, espere. Saia da sala, respire, deixe para responder amanhã. Quase sempre, a resposta de amanhã é melhor.\n\nE diante de uma ofensa, a pergunta de Epicteto: a pessoa disse algo verdadeiro? Então não é ofensa, é informação. Disse algo falso? Então o erro é dela, não seu.\n\nEsta semana, o desafio da manhã é escolher uma situação em que você vai treinar isso."},{"icon":"🏛️","name":"Perda e mudança","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Tudo o que você tem, você tem emprestado: pessoas, saúde, coisas, posições. Os estoicos repetiam isso não para entristecer, mas para que a perda não pegasse ninguém de surpresa.\n\nEpicteto sugeria uma prática dura e útil: ao se despedir de alguém que ama, lembrar que aquela pode ser a última vez. Não para sofrer antes da hora, mas para estar presente agora.\n[[page]]\nMudança não é exceção, é a regra. Marco Aurélio comparava a vida a um rio: a água que passa nunca é a mesma.\n\nDiante de uma perda ou de uma mudança que você não escolheu, a pergunta volta ao primeiro princípio: o que disso depende de mim? O luto é seu, e é legítimo. A forma de seguir em frente também é sua."},{"icon":"🏛️","name":"Fama e opinião dos outros","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"Marco Aurélio, o homem mais poderoso do mundo na época dele, escrevia para si mesmo que a fama era inútil: em pouco tempo, todos que lembram de você também terão sido esquecidos.\n\nA opinião dos outros está do lado de fora da linha do controle. Você pode agir bem; o que vão pensar disso não depende de você.\n[[page]]\nIsso não significa ignorar críticas. Significa separar duas perguntas: \"isso é verdade?\" e \"isso me deixa mal?\". A primeira merece atenção. A segunda é só o ego reclamando.\n\nHoje, repare quantas decisões suas são tomadas para parecer bem, e não para fazer bem."},{"icon":"⚔️","name":"O desafio do dia","description":"De manhã, escolha uma situação do dia em que vai praticar um princípio (uma conversa difícil, o trânsito, uma tarefa chata). À noite, volte aqui e escreva como reagiu.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":6,"dias":[1,2,3,4,5,6],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":480,"preFlight":["Situação escolhida de manhã","Princípio que vou usar","À noite: como reagi de verdade"]},{"icon":"✉️","name":"Carta para daqui a um ano","description":"Escreva na anotação uma carta para você mesmo daqui a um ano: o que aprendeu nestas duas semanas, que princípio quer manter e como espera estar reagindo às dificuldades.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1230,"preFlight":["O que aprendi","O princípio que vou manter","Uma promessa para o eu de daqui a um ano"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c08';

-- Despertar de Ferro (10-despertar-de-ferro.md)
update public.codex_catalog set
  title = 'Despertar de Ferro',
  description = 'Duas semanas de força com o peso do corpo ou carga leve: base, técnica e progressão de verdade.',
  duration_days = 14,
  template = template || jsonb_build_object(
    'title', 'Despertar de Ferro',
    'description', 'Duas semanas de força com o peso do corpo ou carga leve: base, técnica e progressão de verdade.',
    'durationDays', 14,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Base","description":"Técnica dos movimentos e o primeiro teste.","actions":[{"icon":"📘","name":"Progressão vence intensidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Força não vem de treinar até cair. Vem de dar ao corpo um pouco mais do que ele está acostumado, deixar ele se recuperar e repetir. O nome disso é sobrecarga progressiva.\n\nO corpo só muda quando precisa. Se o treino é sempre igual, ele se acostuma e para de evoluir. Se é forte demais, você se machuca ou desiste.\n[[page]]\nO ponto certo é desafiador mas controlado: terminar cada série sentindo que ainda daria para fazer duas ou três repetições. Isso é intenso o bastante para o corpo responder e seguro o bastante para você voltar no próximo treino.\n\nConstância ganha de esforço heroico. Três treinos medianos por semana, todas as semanas, fazem muito mais que um treino destruidor por mês.\n[[page]]\nAntes de começar: se você tem dor, lesão, algum problema de saúde ou não treina há muito tempo, fale com um profissional. Dor aguda (pontada, estalo com dor) é sinal de parar, não de insistir.\n\nHoje é o teste inicial. Ele não é para impressionar ninguém: é o seu ponto de partida, para comparar daqui a duas semanas."},{"icon":"🧪","name":"Teste inicial","description":"Faça o máximo de repetições com boa técnica em cada movimento, com descanso entre eles. Anote os números na anotação.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450,"preFlight":["Aquecer 3 minutos (marcha no lugar, rodar braços)","Agachamentos: máximo com boa técnica","Flexões (na versão que você consegue): máximo","Prancha: tempo máximo","Anotar os números"]},{"icon":"🏋️","name":"Treino base","description":"3 séries de cada movimento (agachamento, flexão, remada, prancha), parando 2 ou 3 repetições antes da falha. Descanso de 1 minuto entre séries.","duration":30,"difficulty":3,"actionType":"Ação Recorrente","repetitions":3,"dias":[2,4,6],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":450,"briefing":"Quatro movimentos, com o peso do corpo ou carga leve:\n\n1. Agachamento (ou agachamento até uma cadeira, para começar)\n2. Flexão de braço (no chão, nos joelhos ou apoiado na parede/mesa)\n3. Remada (com mochila carregada, garrafão ou elástico)\n4. Prancha (segurar a posição, em segundos)\n\nFase 1: 3 séries de cada, parando 2 ou 3 repetições antes de não conseguir mais.\nFase 2: +1 série, ou +2 repetições por série, a cada treino.","preFlight":["Espaço livre e água por perto","Aquecimento de 3 minutos","3 séries de cada movimento","Nenhuma dor aguda"]},{"icon":"📘","name":"A técnica dos quatro movimentos","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[2],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Agachamento: pés na largura dos ombros, desça como quem vai sentar numa cadeira atrás de você, peito aberto, joelhos na direção dos pés. Desça até onde conseguir sem tirar o calcanhar do chão. Se for difícil, use uma cadeira de verdade como alvo.\n\nFlexão: corpo reto como uma tábua, mãos um pouco mais abertas que os ombros. Se no chão for pesado, apoie os joelhos ou faça com as mãos numa mesa ou parede. Quanto mais alto o apoio, mais fácil.\n[[page]]\nRemada: incline o tronco à frente com as costas retas, segure a mochila carregada (ou garrafão, ou elástico) e puxe em direção ao umbigo, apertando as costas. Desça devagar.\n\nPrancha: antebraços no chão, corpo reto da cabeça aos pés, barriga firme. Não deixe o quadril cair nem subir demais. Conte o tempo.\n[[page]]\nRegra geral: movimento controlado, sem pressa, especialmente na descida. Técnica boa com poucas repetições vale mais que muitas repetições malfeitas.\n\nSe puder, grave um vídeo seu fazendo cada movimento e compare com a descrição."},{"icon":"📘","name":"Recuperação faz parte do treino","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"O músculo não cresce durante o treino. Cresce depois, enquanto você descansa. O treino é o estímulo; a recuperação é onde a mudança acontece.\n\nÉ por isso que os treinos desta campanha têm um dia de intervalo. Treinar o mesmo grupo todo dia, sem descanso, atrapalha mais do que ajuda.\n[[page]]\nTrês coisas sustentam a recuperação:\n\n— Sono: é quando o corpo mais se reconstrói. Noites curtas atrasam a evolução.\n— Proteína: presente nas refeições ao longo do dia (ovos, carnes, peixes, feijões, laticínios).\n— Movimento leve nos dias de folga: caminhar ajuda mais que ficar parado.\n\nUm pouco de dor muscular um ou dois dias depois do treino é normal. Dor nas articulações ou dor aguda não é."},{"icon":"📝","name":"Log do treino","description":"Na anotação, registre o que fez em cada movimento (repetições, carga, tempo da prancha) e como o corpo respondeu.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":3,"dias":[2,4,6],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":495,"preFlight":["Repetições de cada série","Carga usada (se usou)","Como me senti (fácil, no ponto, pesado)"]},{"icon":"🔁","name":"Revisão da semana","description":"Releia os logs da semana. Na anotação, escreva o que ficou mais fácil e em que movimento você vai subir primeiro na próxima fase.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1140}]},{"level":2,"title":"Fase 2: Sobrecarga","description":"Subir um pouco a cada treino e comparar.","actions":[{"icon":"📘","name":"Como subir sem se machucar","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Agora começa a sobrecarga. A regra é subir uma coisa de cada vez, e pouco: uma série a mais, ou duas repetições a mais por série. Nunca as duas no mesmo dia.\n\nSe a técnica piorar quando você sobe, volte um passo. O objetivo é mais trabalho com a mesma qualidade, não mais trabalho de qualquer jeito.\n[[page]]\nOutras formas de progredir sem aumentar o número: descer mais devagar, fazer uma pausa de dois segundos embaixo do agachamento, baixar o apoio da flexão (da parede para a mesa, da mesa para o chão).\n\nOuça o corpo. Cansaço muscular é esperado. Dor aguda, nas articulações ou que piora durante o movimento, é sinal para parar e, se continuar, procurar um profissional."},{"icon":"🏋️","name":"Treino com sobrecarga","description":"Os mesmos quatro movimentos, com +1 série ou +2 repetições por série em relação ao treino anterior. Mantenha a técnica.","duration":45,"difficulty":3,"actionType":"Ação Recorrente","repetitions":3,"dias":[1,3,5],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":450,"briefing":"Quatro movimentos, com o peso do corpo ou carga leve:\n\n1. Agachamento (ou agachamento até uma cadeira, para começar)\n2. Flexão de braço (no chão, nos joelhos ou apoiado na parede/mesa)\n3. Remada (com mochila carregada, garrafão ou elástico)\n4. Prancha (segurar a posição, em segundos)\n\nFase 1: 3 séries de cada, parando 2 ou 3 repetições antes de não conseguir mais.\nFase 2: +1 série, ou +2 repetições por série, a cada treino.","preFlight":["Aquecimento de 3 minutos","Subir uma variável só (série ou repetição)","Técnica igual ou melhor que na semana 1","Nenhuma dor aguda"]},{"icon":"📝","name":"Log do treino","description":"Na anotação, registre o que fez em cada movimento (repetições, carga, tempo da prancha) e como o corpo respondeu.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":3,"dias":[1,3,5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":510,"preFlight":["Repetições de cada série","Carga usada (se usou)","Como me senti (fácil, no ponto, pesado)"]},{"icon":"📘","name":"Comer para construir","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Treino é o estímulo, mas o material para construir vem da comida. Sem isso, o corpo não tem com o que se adaptar.\n\nNão precisa de dieta complicada nem de suplemento. Uma regra simples: ter uma fonte de proteína em cada refeição principal — ovos, frango, carne, peixe, feijão, lentilha, iogurte, queijo.\n[[page]]\nBeber água ao longo do dia e comer comida de verdade na maior parte do tempo já resolve muito. Restrições fortes, especialmente cortar muito a comida, atrapalham o ganho de força.\n\nNecessidades específicas (doenças, dietas especiais, objetivos de peso) pedem a orientação de um nutricionista."},{"icon":"🏆","name":"Teste final","description":"Repita o teste do primeiro dia, do mesmo jeito, e compare os números na anotação.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450,"preFlight":["Mesmo aquecimento do teste inicial","Mesmos movimentos e versões","Anotar e comparar com o dia 1"]}]}]$modelo$::jsonb)
where id = '7f31c3d8-7a9a-4d4e-9b36-4f79a5f42a01';

-- Finanças com Intenção (11-financas-com-intencao.md)
update public.codex_catalog set
  title = 'Finanças com Intenção',
  description = 'Duas semanas para saber para onde vai o seu dinheiro e começar a pagar a si mesmo primeiro.',
  duration_days = 14,
  template = template || jsonb_build_object(
    'title', 'Finanças com Intenção',
    'description', 'Duas semanas para saber para onde vai o seu dinheiro e começar a pagar a si mesmo primeiro.',
    'durationDays', 14,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Raio-x","description":"Anotar tudo e enxergar o mês.","actions":[{"icon":"📘","name":"Controlar não é construir","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Muita gente acha que organizar dinheiro é cortar tudo o que dá prazer. Não é. Organizar é decidir para onde o dinheiro vai, em vez de descobrir no fim do mês para onde ele foi.\n\nExistem duas fases nisso. A primeira é controlar: saber quanto entra, quanto sai e onde. A segunda é construir: fazer sobrar e dar um destino a essa sobra.\n[[page]]\nSem a primeira, a segunda não acontece. Você não consegue guardar o que não sabe que tem.\n\nPor isso esta semana é só de observação. Nada de cortar, nada de culpa. Você vai anotar todos os gastos de todos os dias, até o café, até o Pix pequeno.\n[[page]]\nAnotar parece chato, mas faz uma coisa poderosa sozinho: você passa a perceber o gasto na hora em que ele acontece. Muita gente gasta menos só por estar anotando.\n\nEscolha agora onde vai anotar (uma nota no celular, uma planilha, um caderno) e comece hoje."},{"icon":"🧾","name":"Anotar os gastos do dia","description":"Anote todos os gastos de hoje, com valor e categoria (casa, comida, transporte, lazer, outros). Vale tudo, até o pequeno.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260,"preFlight":["Conferir extrato e carteira","Anotar cada gasto com valor","Colocar uma categoria em cada um"]},{"icon":"📘","name":"Os vazamentos","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"O dinheiro raramente some num gasto grande. Some em pequenos vazamentos que se repetem: o delivery da semana, o café de todo dia, a assinatura que você esqueceu, as taxas do banco, a compra por impulso de madrugada.\n\nUm gasto pequeno repetido todo dia vira um gasto grande no mês. E no ano, vira muito.\n[[page]]\nOlhe para os seus três primeiros dias de anotação. Aparece algo que se repete? Algum gasto que você nem lembrava de ter feito?\n\nO objetivo não é proibir. Um café que te faz bem pode valer cada centavo. O objetivo é que cada gasto repetido seja uma escolha, e não um piloto automático.\n\nAmanhã é dia de caçar o vazamento mais escondido de todos: as assinaturas."},{"icon":"✂️","name":"Revisar assinaturas","description":"Olhe a fatura do cartão e os apps de assinatura. Liste tudo o que é cobrado todo mês e cancele pelo menos uma que você não usa.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Listar as cobranças recorrentes","Marcar as que não uso","Cancelar pelo menos uma","Anotar quanto vou economizar por mês"]},{"icon":"📘","name":"Gasto fixo e gasto variável","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Gasto fixo é o que vem todo mês, mais ou menos igual: aluguel, contas, escola, transporte, assinaturas. Gasto variável é o que muda: comida fora, lazer, roupas, compras.\n\nOs fixos são difíceis de mudar rápido, mas cada redução vale para todos os meses seguintes. Os variáveis mudam fácil, mas exigem atenção todo dia.\n[[page]]\nSeparar os dois ajuda a enxergar: quanto do seu dinheiro já está comprometido antes do mês começar? E quanto sobra para as decisões do dia a dia?\n\nNo fim da semana você vai montar o mapa do mês em cinco categorias. Comece a reparar quais dos seus gastos são fixos e quais são variáveis."},{"icon":"🗺️","name":"O mapa do mês","description":"Com a semana de anotações, monte uma estimativa do mês em 5 categorias (casa, comida, transporte, lazer, outros). Na anotação, escreva os números e o que mais te surpreendeu.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Somar a semana por categoria","Multiplicar por 4 (mais ou menos o mês)","Somar os gastos fixos","Comparar com o que entra"]}]},{"level":2,"title":"Fase 2: Pagar a si mesmo","description":"Reserva primeiro, e no automático.","actions":[{"icon":"📘","name":"Reserva de emergência primeiro","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Antes de pensar em investir, o primeiro objetivo costuma ser uma reserva de emergência: um dinheiro guardado só para imprevistos, como uma despesa médica, um conserto ou um mês sem renda.\n\nSem ela, qualquer imprevisto vira dívida, e dívida cara (cartão, cheque especial) é a forma mais rápida de o dinheiro ir embora.\n[[page]]\nUma referência comum é juntar o suficiente para alguns meses de gastos essenciais. Mas não precisa começar pelo número final: começar com qualquer valor, todo mês, é o que importa.\n\nEssa reserva fica num lugar seguro e fácil de sacar, separado da conta do dia a dia, para você não gastar sem querer. Onde exatamente depende da sua situação; vale pesquisar ou pedir orientação.\n\nEsta semana, continue anotando os gastos, agora com uma meta por categoria baseada no seu mapa."},{"icon":"🧾","name":"Anotar os gastos (com meta)","description":"Anote os gastos de hoje e compare com a meta da categoria que você definiu a partir do mapa do mês.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":6,"dias":[1,2,3,4,5,6],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260,"preFlight":["Anotar cada gasto","Conferir a meta da categoria","Se passou, anotar por quê"]},{"icon":"📘","name":"Automatizar vence força de vontade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Guardar o que sobra no fim do mês quase nunca funciona, porque quase nunca sobra. O gasto se ajusta ao dinheiro que está disponível.\n\nA inversão que muda o jogo: pagar a si mesmo primeiro. No dia em que o dinheiro entra, uma parte já vai para a reserva, antes de você ter a chance de gastar.\n[[page]]\nE o melhor jeito de fazer isso é tirando a decisão da sua mão: uma transferência automática programada para o dia do pagamento. Uma vez configurada, ela acontece sem esforço e sem precisar de força de vontade.\n\nO valor pode ser pequeno no começo. Um valor pequeno que acontece todo mês vale mais do que um valor grande que você nunca transfere."},{"icon":"🏁","name":"Transferência automática criada","description":"Programe no seu banco uma transferência automática para a reserva, no dia em que o dinheiro entra. Qualquer valor serve para começar. Na anotação, escreva o valor e o dia.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Escolher onde fica a reserva (separado da conta do dia a dia)","Definir o valor mensal","Programar a transferência para o dia do pagamento"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42d09';

-- Maestria Financeira (12-maestria-financeira.md)
update public.codex_catalog set
  title = 'Maestria Financeira',
  description = 'Três semanas para colocar o dinheiro na ordem certa: dívidas, reserva e o primeiro passo para fazer ele crescer, terminando com um plano do ano escrito.',
  duration_days = 21,
  template = template || jsonb_build_object(
    'title', 'Maestria Financeira',
    'description', 'Três semanas para colocar o dinheiro na ordem certa: dívidas, reserva e o primeiro passo para fazer ele crescer, terminando com um plano do ano escrito.',
    'durationDays', 21,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Mentalidade de construtor","description":"Patrimônio, juros e o custo das dívidas.","actions":[{"icon":"📘","name":"Renda não é patrimônio","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Renda é o que entra todo mês. Patrimônio é o que fica: dinheiro guardado, bens, investimentos, menos as dívidas. Muita gente com renda alta tem patrimônio quase zero, porque tudo o que entra sai.\n\nQuem constrói patrimônio pensa diferente: cada real que sobra é um tijolo. Não é sobre ganhar mais primeiro. É sobre fazer ficar uma parte do que já entra.\n[[page]]\nA conta que importa é simples: patrimônio de hoje menos patrimônio do ano passado. Se esse número cresce, você está construindo, mesmo devagar. Se fica parado ou cai, você está só girando dinheiro.\n\nEsta campanha tem uma ordem: primeiro saber onde você está, depois arrumar a base (dívidas e reserva), por último fazer o dinheiro crescer. Pular etapas é o erro mais comum.\n\nHoje começa o registro diário de gastos, que vai acompanhar as três semanas."},{"icon":"🧾","name":"Anotar os gastos do dia","description":"Anote todos os gastos de hoje com valor e categoria. Vale tudo, até o pequeno.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260},{"icon":"🗺️","name":"Mapa das dívidas","description":"Liste todas as dívidas: para quem, quanto falta, valor da parcela e taxa de juros por mês. Na anotação ou numa planilha.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[2],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Cartão de crédito (inclusive parcelado)","Cheque especial","Empréstimos e financiamentos","Dívidas com pessoas","Taxa de juros de cada uma"]},{"icon":"📘","name":"Juros a favor e contra","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Juros compostos são juros sobre juros. No primeiro mês você ganha (ou paga) juros sobre o valor inicial; no segundo, sobre o valor inicial mais os juros do primeiro mês; e assim por diante.\n\nNo começo a diferença parece pequena. Com o tempo, ela vira uma curva que dispara para cima. É por isso que tempo é o ingrediente mais poderoso, tanto para crescer quanto para afundar.\n[[page]]\nA favor: um valor guardado todo mês, rendendo por anos, cresce muito mais do que a soma do que você depositou. Começar cedo, mesmo com pouco, costuma valer mais do que começar tarde com muito.\n\nContra: a mesma matemática faz uma dívida no cartão ou no cheque especial crescer num ritmo assustador. Em poucos meses, o valor devido pode ficar muito maior que o original.\n\nA primeira regra de quem constrói: deixar os juros compostos trabalharem a seu favor e nunca contra."},{"icon":"📘","name":"O custo da dívida cara","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Nem toda dívida é igual. Um financiamento de longo prazo com juros baixos é muito diferente do rotativo do cartão ou do cheque especial, que estão entre as taxas mais altas que existem.\n\nPagar uma dívida cara é, na prática, um dos \"investimentos\" de retorno mais alto que existem: cada real que deixa de pagar juros de cartão é um real que não some.\n[[page]]\nOlhe o seu mapa das dívidas e ordene pela taxa de juros, da maior para a menor. As do topo são as urgentes.\n\nSe a dívida estiver fora de controle, renegociar costuma ser possível: trocar uma dívida cara por uma mais barata, ou negociar desconto para pagar à vista. Instituições e programas de renegociação existem para isso.\n\nNa próxima semana você vai montar a reserva e atacar a primeira dívida da lista."},{"icon":"🔁","name":"Revisão da semana 1","description":"Releia a semana. Na anotação: seu patrimônio aproximado hoje (o que tem menos o que deve), a dívida mais cara e quanto sobra por mês.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Patrimônio aproximado de hoje","A dívida de juros mais altos","Quanto sobra (ou falta) por mês"]}]},{"level":2,"title":"Fase 2: Reserva e ordem","description":"Montar a reserva e atacar a dívida certa primeiro.","actions":[{"icon":"📘","name":"A reserva de emergência","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"A reserva de emergência é o dinheiro que separa um imprevisto de uma dívida. Sem ela, o conserto do carro vai para o cartão, e o cartão começa a cobrar juros.\n\nUma referência comum é ter alguns meses dos seus gastos essenciais guardados: moradia, comida, contas, transporte. Quem tem renda mais instável costuma precisar de mais.\n[[page]]\nNão precisa juntar tudo de uma vez. O passo de hoje é definir a meta final e fazer o primeiro depósito, de qualquer valor.\n\nAo mesmo tempo, se você tem dívida muito cara, existe um equilíbrio: uma reserva pequena para não voltar ao cartão no primeiro imprevisto, e o resto do esforço indo para quitar a dívida. Depois que a dívida acaba, a reserva cresce até a meta."},{"icon":"🧾","name":"Anotar os gastos (com meta)","description":"Anote os gastos e compare com uma meta por categoria, definida a partir da semana 1.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260},{"icon":"🎯","name":"Meta e primeiro depósito da reserva","description":"Calcule seus gastos essenciais de um mês, defina a meta da reserva e faça o primeiro depósito numa conta separada. Anote os números.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[2],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200},{"icon":"📘","name":"Qual dívida atacar primeiro","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Existem dois jeitos clássicos de quitar várias dívidas.\n\nO primeiro é atacar a de juros mais altos, pagando o mínimo nas outras. É o que economiza mais dinheiro, porque elimina primeiro o que mais cresce.\n\nO segundo é atacar a menor dívida primeiro, para ganhar ânimo ao ver uma acabar logo, e depois rolar esse valor para a próxima.\n[[page]]\nMatematicamente, a de juros mais altos ganha. Na prática, a que você consegue manter ganha. Se você precisa de vitórias rápidas para não desistir, comece pela menor.\n\nO importante é ter um plano escrito: qual dívida, quanto por mês a mais, e em quanto tempo ela acaba. É isso que você vai montar amanhã."},{"icon":"⚔️","name":"Plano contra a dívida cara","description":"Escolha a dívida-alvo e escreva o plano: quanto a mais por mês, em quanto tempo acaba, e se dá para renegociar. Se não tiver dívida cara, use este tempo para aumentar o depósito mensal da reserva.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200},{"icon":"📘","name":"Onde guardar a reserva","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"A reserva tem três exigências, nesta ordem: segurança, liquidez (poder sacar rápido quando precisar) e só depois rendimento.\n\nPor isso ela não costuma ir para aplicações que variam muito de valor nem para as que prendem o dinheiro por anos. O objetivo dela não é render muito, é estar lá, inteira, no dia do imprevisto.\n[[page]]\nTambém não deve ficar misturada com a conta do dia a dia, ou você acaba gastando sem perceber.\n\nExistem várias opções de renda fixa conservadora com liquidez diária. Antes de escolher, compare: se o dinheiro tem garantia, quanto rende, se tem taxas e em quanto tempo dá para sacar. Na dúvida, vale buscar orientação de um profissional certificado."},{"icon":"🔁","name":"Revisão da semana 2","description":"Na anotação: quanto já tem na reserva, qual é a meta e como está o plano da dívida.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200}]},{"level":3,"title":"Fase 3: O primeiro movimento","description":"Risco, prazo e diversificação, e o plano do ano.","actions":[{"icon":"📘","name":"Risco, prazo e retorno","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Todo investimento equilibra três coisas: risco (a chance de o valor cair), prazo (quando você vai precisar do dinheiro) e retorno (quanto pode render).\n\nQuanto maior o retorno prometido, maior costuma ser o risco. Promessa de retorno alto e garantido é sinal de alerta, não de oportunidade.\n[[page]]\nO prazo decide muito. Dinheiro que você vai usar em meses não deve ficar onde pode cair muito. Dinheiro para daqui a muitos anos aguenta mais oscilação, porque tem tempo para se recuperar.\n\nAntes de qualquer investimento, três perguntas: para que é esse dinheiro, quando vou precisar dele e quanto suportaria ver ele cair sem me desesperar."},{"icon":"🧾","name":"Anotar os gastos (com meta)","description":"Anote os gastos e compare com uma meta por categoria, definida a partir da semana 1.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":6,"dias":[1,2,3,4,5,6],"context":{"timeOfDay":"night","energyLevel":"low"},"scheduledStartTime":1260},{"icon":"📘","name":"Não colocar tudo num lugar só","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Diversificar é espalhar o dinheiro em coisas diferentes, para que um problema numa delas não derrube tudo.\n\nPode ser entre tipos de investimento, entre instituições, entre prazos. A ideia é a mesma do ditado: não colocar todos os ovos na mesma cesta.\n[[page]]\nPara quem está começando, diversificar não significa ter vinte investimentos. Significa não depender de uma aposta só e entender cada coisa em que coloca dinheiro.\n\nUma regra útil: se você não consegue explicar em duas frases como um investimento ganha dinheiro, ainda não é hora de colocar dinheiro nele."},{"icon":"🔎","name":"Comparar duas opções conservadoras","description":"Pesquise duas opções conservadoras para o dinheiro de longo prazo e compare: garantia, rendimento, taxas, impostos e prazo de saque. Anote numa tabela simples.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200},{"icon":"📘","name":"Custos que comem o rendimento","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1170,"briefing":"Taxa de administração, taxa de corretagem, impostos, inflação: cada uma tira um pedaço do rendimento. Uma diferença de 1% ao ano parece pequena, mas, com juros compostos, ao longo de muitos anos vira uma diferença grande.\n\nPor isso, ao comparar opções, olhe sempre o rendimento já descontados os custos e impostos.\n[[page]]\nA inflação é o custo invisível: se o seu dinheiro rende menos que ela, ele perde poder de compra, mesmo que o número na tela aumente.\n\nAmanhã você junta tudo num plano do ano: quanto guardar por mês, para onde vai cada parte e qual é a próxima meta."},{"icon":"🏁","name":"O plano do ano","description":"Escreva na anotação o seu plano financeiro dos próximos 12 meses: meta da reserva, plano das dívidas, valor mensal guardado e para onde vai cada parte. Revise daqui a 3 meses.","duration":45,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Meta e prazo da reserva","Data prevista para quitar a dívida cara","Valor guardado por mês, no automático","Próxima revisão marcada"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42e05';

-- Liderança sem Cargo (13-lideranca-sem-cargo.md)
update public.codex_catalog set
  title = 'Liderança sem Cargo',
  description = 'Três semanas para ganhar influência onde você está: ser confiável, ser útil e puxar uma iniciativa do começo ao fim.',
  duration_days = 21,
  template = template || jsonb_build_object(
    'title', 'Liderança sem Cargo',
    'description', 'Três semanas para ganhar influência onde você está: ser confiável, ser útil e puxar uma iniciativa do começo ao fim.',
    'durationDays', 21,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Confiável","description":"Cumprir, avisar, escrever claro.","actions":[{"icon":"📘","name":"Influência começa na confiança","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Liderança não vem do cargo. Vem de as pessoas quererem te seguir. E ninguém segue quem não é confiável.\n\nAntes de carisma, ideias ou visão, vem uma coisa básica: você faz o que diz que vai fazer? Se sim, as pessoas passam a contar com você. Se não, nenhuma ideia boa compensa.\n[[page]]\nConfiança se constrói em coisas pequenas: responder quando disse que responderia, entregar no prazo combinado, chegar na hora, lembrar do que prometeu numa reunião.\n\nCada promessa cumprida é um depósito. Cada promessa esquecida é um saque, e saque pesa mais que depósito.\n[[page]]\nEsta semana você vai registrar, todo dia, os compromissos que assumiu e se cumpriu. Não para se culpar: para enxergar.\n\nA primeira descoberta costuma ser que prometemos coisas demais sem perceber. \"Depois te mando\", \"vou ver isso\", \"a gente marca\". Cada uma é um compromisso."},{"icon":"📒","name":"Registro de compromissos","description":"Na anotação: o que prometi hoje (para quem e até quando) e o que cumpri do que estava pendente.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1080,"preFlight":["Compromissos novos de hoje","Compromissos cumpridos","Algum que preciso renegociar?"]},{"icon":"📘","name":"Avisar antes de atrasar","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Atrasos acontecem. O que destrói a confiança não é o atraso: é a surpresa. Descobrir no dia do prazo que a coisa não vai sair é muito pior do que ser avisado com antecedência.\n\nQuem avisa cedo dá ao outro a chance de se reorganizar. Quem some deixa o outro sem saída.\n[[page]]\nA regra: assim que perceber que não vai cumprir, avise. Diga o que aconteceu, o que já está pronto e qual é o novo prazo realista.\n\nE menos promessas, mais cumprimento. Antes de dizer \"faço até amanhã\", pergunte a si mesmo se é verdade. Prometer menos e entregar mais constrói mais confiança do que o contrário."},{"icon":"📘","name":"Escrever claro: contexto, pedido, prazo","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Muita confusão no trabalho nasce de mensagem mal escrita. O outro não sabe o que você quer, para quando, nem por quê.\n\nUma estrutura simples resolve quase tudo: contexto (o que está acontecendo), pedido (o que exatamente você precisa) e prazo (para quando).\n[[page]]\nEm vez de \"dá uma olhada naquilo quando puder\", escreva: \"Estou fechando o relatório do mês (contexto). Pode revisar os números da página 3 (pedido) até quinta às 12h (prazo)?\"\n\nMensagens claras economizam idas e vindas, e as pessoas passam a gostar de receber as suas. Nos próximos dois dias, escreva pelo menos uma mensagem importante nesse formato."},{"icon":"✍️","name":"Uma mensagem no formato claro","description":"Escreva uma mensagem importante usando contexto, pedido e prazo. Cole na anotação como ficou.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":2,"dias":[5,6],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":600},{"icon":"🔁","name":"Revisão da semana 1","description":"Na anotação: quantos compromissos assumi, quantos cumpri e o que aprendi sobre prometer.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1140}]},{"level":2,"title":"Fase 2: Útil para o time","description":"Tirar atrito do caminho dos outros e dar retorno que ajuda.","actions":[{"icon":"📘","name":"O atrito invisível","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Em todo grupo existem pequenas coisas que atrapalham todo mundo e ninguém resolve: o arquivo que ninguém acha, a reunião sem pauta, a dúvida que se repete toda semana, o processo que tem um passo inútil.\n\nCada uma rouba alguns minutos de várias pessoas, todos os dias. Ninguém resolve porque não é \"trabalho de ninguém\".\n[[page]]\nQuem remove esses atritos vira, aos poucos, a pessoa a quem os outros recorrem. Não por cargo: por ser útil.\n\nEsta semana, todo dia útil, encontre e resolva um atrito pequeno: organizar uma pasta, escrever um passo a passo, propor uma pauta, responder de vez uma dúvida que sempre volta."},{"icon":"🔧","name":"Remover um atrito","description":"Encontre um atrito pequeno no seu grupo e resolva. Na anotação, diga qual foi e quem se beneficia.","duration":30,"difficulty":2,"actionType":"Ação Recorrente","repetitions":5,"dias":[1,2,3,4,5],"context":{"timeOfDay":"afternoon","energyLevel":"medium"},"scheduledStartTime":960},{"icon":"📘","name":"Retorno que ajuda","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Dar retorno (o famoso feedback) é uma das coisas que mais ajudam e menos são feitas direito. Ou ninguém fala nada, ou fala de um jeito que machuca e não ajuda.\n\nRetorno útil é específico, sobre o comportamento (não sobre a pessoa) e pensado para ajudar.\n[[page]]\nUm formato simples: situação, o que você observou, o efeito. \"Na apresentação de ontem (situação), você começou pelos números (observação), e isso deixou todo mundo entendendo o problema logo (efeito).\"\n\nFunciona para elogiar e para apontar algo a melhorar. O elogio específico, aliás, costuma ser mais raro e mais valioso do que a crítica."},{"icon":"💬","name":"Um retorno útil","description":"Dê um retorno específico a alguém (situação, observação, efeito), de preferência um elogio sincero. Anote como foi.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":2,"dias":[3,5],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1020},{"icon":"📘","name":"Reconhecer em público","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Quem lidera divide o crédito. Reconhecer o trabalho dos outros na frente do grupo custa nada e constrói muito: as pessoas se sentem vistas e passam a confiar em quem as reconhece.\n\nO inverso também vale: corrigir em particular, reconhecer em público.\n[[page]]\nNa próxima semana você vai propor e tocar uma iniciativa. Comece a pensar: dos atritos que você viu, qual valeria um projeto pequeno? Algo que dê para fazer em uma semana e que melhore a vida do grupo."},{"icon":"🔁","name":"Revisão da semana 2","description":"Na anotação: os atritos que removi, os retornos que dei e uma ideia de iniciativa para a próxima semana.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1140}]},{"level":3,"title":"Fase 3: Iniciativa","description":"Propor algo pequeno e entregar.","actions":[{"icon":"📘","name":"Propor algo pequeno","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Iniciativa não precisa ser grandiosa. Na verdade, as melhores começam pequenas: algo que dê para fazer em poucos dias, com começo, meio e fim claros.\n\nProjeto grande demais morre no meio. Projeto pequeno termina e abre espaço para o próximo.\n[[page]]\nUma proposta boa cabe em poucas linhas: o problema (o que atrapalha), a proposta (o que você vai fazer), o resultado esperado e o prazo.\n\nEscreva a sua hoje e mostre para quem precisa saber ou aprovar. Mostrar antes evita surpresas e transforma a ideia em compromisso público."},{"icon":"📝","name":"Escrever a proposta","description":"Escreva a proposta da iniciativa em poucas linhas (problema, proposta, resultado, prazo) e mostre para quem precisa saber.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":600},{"icon":"🚀","name":"Tocar a iniciativa","description":"Avance a iniciativa um passo concreto. Na anotação, registre o que fez e o que falta.","duration":30,"difficulty":3,"actionType":"Ação Recorrente","repetitions":5,"dias":[2,3,4,5,6],"context":{"timeOfDay":"afternoon","energyLevel":"high"},"scheduledStartTime":900},{"icon":"📘","name":"Quando ninguém pediu","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Toda iniciativa encontra resistência: alguém que não vê a necessidade, alguém que acha que não é sua função, alguém que só não gosta de mudança.\n\nIsso é normal. A resposta não é brigar, é mostrar: resultados pequenos convencem mais que argumentos.\n[[page]]\nEnvolva as pessoas afetadas, pergunte o que acham, incorpore as boas ideias. Iniciativa que vira \"nossa\" anda mais rápido que iniciativa que é só \"sua\".\n\nE se a ideia não for aceita, você ainda ganhou: mostrou que se importa e que age, o que é a base da influência."},{"icon":"📘","name":"Fechar o ciclo","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"A diferença entre quem tem ideias e quem lidera é que o segundo termina. E terminar inclui contar que terminou.\n\nFechar o ciclo é mostrar o que foi feito, o resultado e o que aprendeu, e reconhecer quem ajudou.\n[[page]]\nPrepare para o fim da semana uma apresentação curta: três ou quatro frases, ou uma mensagem bem escrita. O que era o problema, o que foi feito, o que mudou e quem ajudou."},{"icon":"🏁","name":"Apresentar o resultado","description":"Apresente o resultado da iniciativa para quem decide ou para o grupo: problema, o que foi feito, o que mudou e quem ajudou. Na anotação, registre como foi recebido.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":600,"preFlight":["O problema em uma frase","O que foi feito","O que mudou","Reconhecer quem ajudou"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42e04';

-- Construção de Identidade (14-construcao-de-identidade.md)
update public.codex_catalog set
  title = 'Construção de Identidade',
  description = 'Três semanas para separar os valores que você herdou dos que você escolhe, e terminar com um manifesto pessoal de uma página.',
  duration_days = 21,
  template = template || jsonb_build_object(
    'title', 'Construção de Identidade',
    'description', 'Três semanas para separar os valores que você herdou dos que você escolhe, e terminar com um manifesto pessoal de uma página.',
    'durationDays', 21,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Auditoria","description":"De onde vêm os seus valores.","actions":[{"icon":"📘","name":"Herdado ou escolhido","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Muito do que você acredita sobre como viver não foi escolhido: foi absorvido. Da família, da escola, da religião, dos amigos, das redes. Coisas como \"trabalho é sofrimento\", \"dinheiro é sujo\", \"homem não chora\", \"tem que agradar todo mundo\".\n\nAlgumas dessas crenças são ótimas e vale mantê-las. Outras você carrega sem nunca ter perguntado se concorda.\n[[page]]\nIdentidade escolhida começa com uma pergunta simples, feita para cada crença: eu acredito nisso porque pensei a respeito ou porque sempre foi assim?\n\nNão é sobre rejeitar o passado. É sobre olhar para ele e decidir, conscientemente, o que fica.\n[[page]]\nEsta semana, toda noite, uma pergunta de escrita. Hoje: liste cinco regras sobre como viver que você aprendeu em casa. Para cada uma, escreva se ainda concorda, se concorda em parte ou se não concorda mais."},{"icon":"✍️","name":"Escrita da noite","description":"Responda na anotação a pergunta do dia (está na aula mais recente). Escreva sem editar, pelo menos cinco linhas. Perguntas de apoio para os dias sem aula: \"Quem eu admiro, e por quê?\", \"Quando me senti mais eu mesmo?\", \"O que eu faria se ninguém fosse julgar?\"","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1290},{"icon":"📘","name":"O que você tolera","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Os valores aparecem com clareza no que incomoda. Aquilo que você não suporta ver — injustiça, mentira, preguiça, crueldade — aponta para o que você valoriza.\n\nMas existe outra lista, mais incômoda: o que você tolera em você mesmo e não deveria. Hábitos, relações, ambientes, pequenas desonestidades.\n[[page]]\nO que você tolera define você tanto quanto o que você defende. Um valor que nunca é defendido na prática é só uma opinião.\n\nPergunta da noite: o que eu tolero hoje, em mim ou ao meu redor, que vai contra o que eu acredito?"},{"icon":"📘","name":"O que te dá orgulho","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Pense nos momentos da sua vida de que você mais se orgulha. Não os que mais impressionariam os outros: os que você, por dentro, sabe que foram certos.\n\nQuase sempre eles revelam um valor: coragem para dizer algo difícil, lealdade a alguém, persistência quando era mais fácil desistir, honestidade quando ninguém veria.\n[[page]]\nOrgulho verdadeiro é um mapa dos seus valores de fato, não dos que você acha que deveria ter.\n\nPergunta da noite: três momentos de que me orgulho, e que valor estava por trás de cada um."},{"icon":"🔁","name":"Revisão da semana 1","description":"Releia tudo o que escreveu na semana e circule as palavras que se repetem. Na anotação, liste os 6 a 8 valores que mais apareceram.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200}]},{"level":2,"title":"Fase 2: Três princípios","description":"Escolher os inegociáveis e votar neles todo dia.","actions":[{"icon":"📘","name":"Escolher três inegociáveis","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Da lista de valores da semana passada, você vai escolher três. Só três. Não porque os outros não importam, mas porque quem tem dez prioridades não tem nenhuma.\n\nInegociável é aquilo que você mantém mesmo quando custa caro: quando perde dinheiro, quando desagrada alguém, quando dá trabalho.\n[[page]]\nPara cada um, escreva uma frase com as suas palavras. Não \"honestidade\", mas algo como \"eu não minto, nem para facilitar a minha vida\".\n\nA frase precisa ser sua, específica e algo que você consiga verificar se cumpriu ou não."},{"icon":"📝","name":"Escrever os três princípios","description":"Escolha os três valores inegociáveis e escreva cada um como uma frase sua, específica e verificável.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1230},{"icon":"🗳️","name":"Um voto por princípio","description":"Na anotação, para cada princípio: uma coisa que você fez hoje a favor dele. Se não fez, escreva isso também.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":6,"dias":[2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1290},{"icon":"📘","name":"Hábitos são votos","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Você não se torna alguém de uma vez. Torna-se aos poucos, por ações repetidas. Cada vez que você age de acordo com um princípio, é como um voto a favor da pessoa que quer ser.\n\nNinguém precisa de unanimidade. Basta a maioria dos votos ir na direção certa.\n[[page]]\nIsso tira o peso da perfeição. Um dia em que você falhou não apaga quem você está se tornando; é só um voto contra num mar de votos a favor.\n\nE muda a pergunta. Em vez de \"eu sou uma pessoa disciplinada?\", pergunte \"que voto eu dou hoje para a pessoa disciplinada que estou construindo?\"."},{"icon":"📘","name":"Princípio vira regra","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Princípio vago é fácil de trair: \"quero ser saudável\" não diz o que fazer às 23h diante da geladeira. Princípio que vira regra concreta é mais fácil de cumprir.\n\nPara cada princípio, crie uma ou duas regras do dia a dia. \"Eu cuido do meu corpo\" vira \"eu não como depois das 21h\" ou \"eu caminho todo dia útil\".\n[[page]]\nA regra funciona como uma decisão tomada antes: na hora da tentação, você não precisa decidir de novo, só seguir.\n\nEscreva, na anotação de hoje, uma regra para cada um dos seus três princípios."},{"icon":"🔁","name":"Revisão da semana 2","description":"Na anotação: quantos votos cada princípio recebeu e qual foi o mais difícil de manter.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200}]},{"level":3,"title":"Fase 3: Manifesto","description":"Escrever, testar e ajustar.","actions":[{"icon":"📘","name":"O que é um manifesto pessoal","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Um manifesto pessoal é uma página com quem você escolheu ser: seus princípios, suas regras e o que você não aceita. Não é para mostrar a ninguém. É para consultar nos momentos de dúvida.\n\nEle junta tudo o que você fez até aqui: os valores da auditoria, os três princípios, as regras do dia a dia.\n[[page]]\nEscreva na primeira pessoa e no presente: \"eu sou\", \"eu faço\", \"eu não\". Frases curtas, que você consiga ler em um minuto.\n\nHoje é só o primeiro rascunho. Ele vai ser testado e ajustado durante a semana."},{"icon":"📝","name":"Primeiro rascunho","description":"Escreva o primeiro rascunho do manifesto: seus três princípios, as regras de cada um e o que você não aceita mais. Uma página, na primeira pessoa.","duration":45,"difficulty":3,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"night","energyLevel":"high"},"scheduledStartTime":1230},{"icon":"⚖️","name":"Testar contra a vida real","description":"Na anotação: uma situação de hoje em que o manifesto ajudou a decidir, ou em que ele pareceu errado ou incompleto.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":5,"dias":[2,3,4,5,6],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1290},{"icon":"📘","name":"Quando o manifesto encontra a realidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Todo manifesto bonito encontra um dia difícil: um conflito entre dois princípios, uma situação que ele não previu, uma regra que parecia boa e na prática não funciona.\n\nIsso não significa que o manifesto falhou. Significa que ele está sendo usado.\n[[page]]\nQuando dois princípios brigam — honestidade e gentileza, por exemplo —, a pergunta é qual deles pesa mais naquela situação, e por quê. Anote essas decisões: elas mostram a sua hierarquia de valores real."},{"icon":"📘","name":"Revisar sem trair","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200,"briefing":"Ajustar o manifesto é saudável; abandoná-lo no primeiro incômodo, não. A diferença está no motivo.\n\nMudar porque aprendeu algo novo sobre você ou sobre o mundo é crescimento. Mudar porque a regra ficou inconveniente é desculpa.\n[[page]]\nAntes de mudar uma frase, pergunte: eu mudaria isso se ninguém estivesse me vendo e se não me custasse nada manter? Se a resposta for sim, mude. Se for não, mantenha.\n\nNo fim da semana você fecha a versão final."},{"icon":"🏁","name":"Manifesto de uma página","description":"Escreva a versão final do manifesto, de uma página, e guarde onde possa reler. Marque no planner uma releitura daqui a um mês.","duration":45,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1200,"preFlight":["Três princípios na primeira pessoa","Uma ou duas regras para cada um","O que eu não aceito mais","Releitura marcada daqui a um mês"]}]}]$modelo$::jsonb)
where id = '7f31c3d8-7a9a-4d4e-9b36-4f79a5f42a05';

-- Corpo de Elite (15-corpo-de-elite.md)
update public.codex_catalog set
  title = 'Corpo de Elite',
  description = 'Três semanas juntando treino, sono e comida num plano só, com teste no começo e no fim.',
  duration_days = 21,
  template = template || jsonb_build_object(
    'title', 'Corpo de Elite',
    'description', 'Três semanas juntando treino, sono e comida num plano só, com teste no começo e no fim.',
    'durationDays', 21,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Base","description":"Os três treinos e o sono fixo.","actions":[{"icon":"📘","name":"O triângulo: treino, sono e comida","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Treino sozinho não muda o corpo. Ele é um dos três lados de um triângulo: treino, sono e comida. Se um lado falha, os outros não compensam.\n\nMuita gente treina pesado, dorme mal e come qualquer coisa, e não entende por que não evolui. O treino dá o estímulo; o sono e a comida fazem a mudança acontecer.\n[[page]]\nEsta campanha cuida dos três. Na primeira semana, os treinos de base e o horário fixo de sono. Na segunda, mais volume e a regra da proteína. Na terceira, a semana mais forte.\n\nHoje é o teste inicial: ele mostra onde você está, para comparar no dia 21.\n[[page]]\nAntes de começar: se você tem dor, lesão, problema de saúde ou não treina há muito tempo, fale com um profissional. Dor aguda, pontada ou dor nas articulações é sinal para parar, não para insistir."},{"icon":"🧪","name":"Teste inicial","description":"Anote: máximo de agachamentos e flexões com boa técnica, tempo de prancha e quanto tempo leva para caminhar ou correr 1 km (ou distância que conseguir em 10 minutos).","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450},{"icon":"🏋️","name":"Força","description":"Agachamento, flexão, remada, ponte de glúteo e prancha: 3 séries de cada, parando 2 ou 3 repetições antes da falha.","duration":45,"difficulty":3,"actionType":"Ação Recorrente","repetitions":2,"dias":[2,5],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço.","preFlight":["Aquecimento de 5 minutos","3 séries de cada movimento","Nenhuma dor aguda"]},{"icon":"🧘","name":"Mobilidade","description":"20 a 30 minutos de mobilidade de quadril, ombros e coluna, mais alongamentos das pernas.","duration":30,"difficulty":1,"actionType":"Ação Recorrente","repetitions":2,"dias":[3,6],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço."},{"icon":"🏃","name":"Condicionamento","description":"30 minutos de caminhada rápida, corrida leve ou bicicleta, num ritmo em que dá para falar frases curtas.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço."},{"icon":"🛏️","name":"Dormir no horário","description":"Deite no horário que você escolheu, com o celular fora da cama. A meta é sete horas ou mais.","duration":15,"difficulty":2,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"night","energyLevel":"medium"},"scheduledStartTime":1350},{"icon":"📘","name":"Três tipos de treino","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Um corpo preparado precisa de três capacidades: força (mover e sustentar peso), mobilidade (mover as articulações com amplitude e controle) e condicionamento (coração e pulmão aguentando esforço por mais tempo).\n\nQuem só faz um tipo fica com buracos. Muito forte e travado. Muito flexível e fraco. Muito resistente e frágil.\n[[page]]\nPor isso a semana mistura os três: força duas vezes, mobilidade duas vezes, condicionamento uma vez (duas na próxima fase). Assim cada capacidade é treinada e os músculos têm tempo de se recuperar entre os treinos de força."},{"icon":"📘","name":"Sono é treino","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"É durante o sono profundo que o corpo mais se repara: músculos, hormônios, memória. Dormir pouco deixa o treino menos eficiente, a fome desregulada e a vontade de treinar mais baixa.\n\nPara quem treina, sete horas ou mais por noite costuma ser o mínimo para evoluir bem.\n[[page]]\nHorário fixo de dormir e acordar, quarto escuro e fresco e celular longe da cama resolvem a maior parte. Se você fizer só uma mudança nesta campanha além de treinar, que seja essa."},{"icon":"🔁","name":"Revisão da semana 1","description":"Na anotação: quantos treinos fez, como foi o sono (média de horas) e o que foi mais difícil.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1140}]},{"level":2,"title":"Fase 2: Volume","description":"Mais trabalho e a regra da proteína.","actions":[{"icon":"📘","name":"Mais trabalho, mesma qualidade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Esta semana o volume sobe: uma série a mais nos treinos de força e um treino de condicionamento a mais, mais longo.\n\nA regra de ouro: mais trabalho com a mesma qualidade. Se a técnica piorar, volte um passo. Cansaço muscular é esperado; dor aguda nunca é.\n[[page]]\nCom mais treino, o corpo pede mais recuperação. É por isso que esta semana também entra a regra da proteína. Mais estímulo sem mais material para construir não funciona."},{"icon":"🏋️","name":"Força +1 série","description":"Agachamento, flexão, remada, ponte de glúteo e prancha: 4 séries de cada, parando 2 ou 3 repetições antes da falha.","duration":45,"difficulty":3,"actionType":"Ação Recorrente","repetitions":2,"dias":[1,4],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço.","preFlight":["Aquecimento de 5 minutos","4 séries de cada movimento","Nenhuma dor aguda"]},{"icon":"🏃","name":"Condicionamento","description":"45 minutos de caminhada rápida, corrida leve ou bicicleta, num ritmo em que dá para conversar com esforço.","duration":45,"difficulty":2,"actionType":"Ação Recorrente","repetitions":2,"dias":[2,5],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço."},{"icon":"🧘","name":"Mobilidade","description":"20 a 30 minutos de mobilidade de quadril, ombros e coluna, mais alongamentos das pernas.","duration":30,"difficulty":1,"actionType":"Ação Recorrente","repetitions":2,"dias":[3,6],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço."},{"icon":"🍳","name":"Proteína em cada refeição","description":"À noite, confira: teve uma fonte de proteína em cada refeição principal hoje? Anote o que faltou.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1200},{"icon":"📘","name":"Proteína sem complicar","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"A proteína é o material que o corpo usa para reconstruir os músculos depois do treino. Não precisa de suplemento nem de conta complicada para começar.\n\nUma regra simples funciona para a maioria: uma fonte de proteína em cada refeição principal. Ovos, frango, carne, peixe, feijão, lentilha, grão-de-bico, iogurte, queijo, tofu.\n[[page]]\nQuem tem necessidades específicas — doenças, dietas especiais, objetivos de peso — deve buscar um nutricionista. Para o resto, comida de verdade com proteína em cada prato já resolve muito."},{"icon":"📘","name":"Água e comida de verdade","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Sem dieta da moda: a base é comida de verdade na maior parte do tempo — comida que a sua avó reconheceria — e água ao longo do dia.\n\nUltraprocessados não são proibidos, mas quando viram a maior parte da alimentação, a energia oscila e a recuperação piora.\n[[page]]\nUm teste simples: a cor da urina. Clara a levemente amarela costuma indicar boa hidratação. Escura, beba mais água. Nos dias de treino, beba um pouco mais."},{"icon":"🔁","name":"Revisão da semana 2","description":"Na anotação: treinos feitos, quantos dias bateu a proteína e como o corpo está respondendo.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1140}]},{"level":3,"title":"Fase 3: Intensidade","description":"A semana mais forte e o teste final.","actions":[{"icon":"📘","name":"A semana mais forte","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"A terceira semana é a mais intensa: movimentos mais difíceis (descida mais lenta, pausa embaixo, versão mais difícil da flexão) e condicionamento em intervalos.\n\nIntervalo é alternar esforço forte e recuperação: por exemplo, 1 minuto rápido e 2 minutos leves, repetido algumas vezes. Faz o coração trabalhar mais em menos tempo.\n[[page]]\nIntensidade alta pede mais cuidado: aquecimento sempre, técnica sempre, e parar diante de qualquer dor aguda. Melhor terminar a campanha inteiro do que se machucar no último esforço."},{"icon":"🏋️","name":"Força intensa","description":"Agachamento, flexão, remada, ponte de glúteo e prancha: 4 séries de cada, descendo em 3 segundos e com pausa de 1 segundo embaixo.","duration":45,"difficulty":3,"actionType":"Ação Recorrente","repetitions":2,"dias":[1,4],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço.","preFlight":["Aquecimento de 5 minutos","4 séries lentas de cada movimento","Nenhuma dor aguda"]},{"icon":"🏃","name":"Condicionamento em intervalos","description":"Intervalos na caminhada, corrida ou bicicleta: 5 minutos leve, depois 6 vezes (1 minuto forte + 2 minutos leve) e 7 minutos leve para fechar.","duration":30,"difficulty":2,"actionType":"Ação Recorrente","repetitions":2,"dias":[2,5],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço."},{"icon":"🧘","name":"Mobilidade e descanso ativo","description":"20 a 30 minutos de mobilidade de quadril, ombros e coluna, num ritmo leve. É o dia de o corpo se recuperar sem ficar parado.","duration":30,"difficulty":1,"actionType":"Ação Recorrente","repetitions":2,"dias":[3,6],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":450,"briefing":"— Força (F): agachamento, flexão, remada, ponte de glúteo, prancha — peso do corpo ou carga leve.\n— Mobilidade (M): 20 a 30 minutos de alongamento ativo e mobilidade de quadril, ombros e coluna.\n— Condicionamento (C): caminhada rápida, corrida leve, bicicleta ou circuito, em ritmo que dê para conversar com esforço."},{"icon":"📘","name":"Descansar também é treino","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Na semana mais forte, o descanso fica ainda mais importante. Os dias de mobilidade não são \"dias de folga\": são os dias em que o corpo absorve o treino pesado.\n\nSinais de que você está passando do ponto: cansaço que não passa com uma noite de sono, sono ruim, irritação, dor que não melhora, queda de desempenho.\n[[page]]\nSe aparecerem, troque um treino forte por um leve. Recuar um dia é muito melhor do que parar uma semana por lesão."},{"icon":"📘","name":"Depois da campanha","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":420,"briefing":"Daqui a dois dias a campanha acaba. O corpo que você construiu não acaba junto, desde que você continue.\n\nO plano mais simples para seguir: manter os três tipos de treino na semana, o sono no horário e a proteína em cada refeição. Não precisa ser perfeito: o que mantém é a frequência.\n[[page]]\nUma boa ideia é transformar os treinos desta campanha em ações suas no planner, com os dias da semana que funcionaram melhor para você."},{"icon":"🏆","name":"Teste final","description":"Repita o teste do primeiro dia, do mesmo jeito, e compare os números na anotação. Escreva o que mais mudou além dos números.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"morning","energyLevel":"medium"},"scheduledStartTime":450,"preFlight":["Mesmo aquecimento e mesmas versões dos movimentos","Comparar com o dia 1","O que mudou no sono, na energia e no humor"]}]}]$modelo$::jsonb)
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42e03';

-- Foco Blindado (16-foco-blindado.md)
update public.codex_catalog set
  title = 'Foco Blindado',
  description = 'Três semanas de trabalho profundo: de sessões de 45 minutos até um dia inteiro de foco num projeto só.',
  duration_days = 21,
  template = template || jsonb_build_object(
    'title', 'Foco Blindado',
    'description', 'Três semanas de trabalho profundo: de sessões de 45 minutos até um dia inteiro de foco num projeto só.',
    'durationDays', 21,
    'levels', $modelo$[{"level":1,"title":"Fase 1: Fundamento","description":"Sessões de 45 minutos e o fim do dia fechado.","actions":[{"icon":"📘","name":"O foco profundo virou raro","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Trabalho profundo é aquele feito com a atenção inteira numa tarefa difícil, sem interrupções: escrever algo importante, estudar um assunto complexo, resolver um problema de verdade.\n\nEle é cada vez mais raro, porque o dia moderno é feito de interrupções: mensagens, notificações, reuniões, abas abertas. E justamente por ser raro, vale cada vez mais.\n[[page]]\nFoco é como um músculo. Quem passa o dia pulando de uma coisa para outra perde a capacidade de se concentrar por muito tempo. A boa notícia é que ela volta com treino.\n\nEsta campanha treina esse músculo aos poucos: sessões de 45 minutos na primeira semana, até 90 minutos na terceira, terminando com um dia de 4 horas de trabalho profundo.\n[[page]]\nA regra da sessão é simples: uma tarefa só, decidida antes, sem celular por perto e sem abrir nada que não seja daquela tarefa.\n\nDepois de cada sessão, uma auditoria rápida: o que tentou te interromper? É assim que você descobre os seus maiores ladrões de atenção."},{"icon":"🎯","name":"Sessão de foco (45 min)","description":"45 minutos numa única tarefa importante, decidida antes. Celular em outro cômodo, notificações do computador desligadas, só as abas da tarefa abertas.","duration":45,"difficulty":3,"actionType":"Ação Recorrente","repetitions":5,"dias":[1,2,3,4,5],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":540,"preFlight":["Tarefa escrita antes de começar","Celular fora de alcance","Notificações desligadas","Só o que é da tarefa aberto"]},{"icon":"🔍","name":"Auditoria da sessão","description":"Na anotação: o que tentou interromper a sessão (de fora ou da sua cabeça) e quanto da sessão foi foco de verdade, de 0 a 10.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":5,"dias":[1,2,3,4,5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":585},{"icon":"📘","name":"Preparar o ambiente","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[2],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Força de vontade é fraca contra um ambiente que distrai. Se o celular está na mesa, você vai pegar. Se o e-mail está aberto, você vai olhar.\n\nA estratégia que funciona é tirar a tentação do caminho antes da sessão começar, para não precisar resistir durante.\n[[page]]\nAntes de cada sessão:\n\n— Celular em outro cômodo ou numa gaveta.\n— Notificações do computador desligadas, e-mail e mensagens fechados.\n— Água por perto, para não ter motivo de levantar.\n— Avisar quem está perto, se der: \"vou ficar 45 minutos focado\".\n\nRepare na sua auditoria de ontem: quais interrupções viriam de fora e quais vieram da sua própria cabeça?"},{"icon":"📘","name":"O ritual de encerramento","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[4],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Muita gente não consegue desligar do trabalho à noite porque o dia nunca termina de verdade: ficam pendências soltas na cabeça, voltando o tempo todo.\n\nO ritual de encerramento resolve isso. No fim do dia, alguns minutos para olhar o que ficou aberto, anotar o próximo passo de cada coisa e decidir o que fica para amanhã.\n[[page]]\nQuando tudo está anotado, a cabeça pode soltar. Você sabe que nada vai ser esquecido, porque está escrito.\n\nTermine o ritual com uma frase fixa, dita mentalmente: \"dia encerrado\". Parece bobo, mas sinaliza ao cérebro que o trabalho acabou."},{"icon":"🌇","name":"Encerrar o dia","description":"Revise o que ficou aberto, anote o próximo passo de cada coisa e escolha a tarefa da sessão de amanhã. Termine com \"dia encerrado\".","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":4,"dias":[4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1080,"preFlight":["Pendências anotadas com próximo passo","Tarefa da sessão de amanhã escolhida","\"Dia encerrado\""]},{"icon":"🔁","name":"Revisão da semana 1","description":"Releia as auditorias. Na anotação: seus três maiores ladrões de atenção e o que vai fazer contra cada um na próxima semana.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1110}]},{"level":2,"title":"Fase 2: Profundidade","description":"Sessões de 60 a 75 minutos com a agenda protegida.","actions":[{"icon":"📘","name":"O custo de alternar tarefas","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Quando você troca de uma tarefa para outra, a atenção não troca por inteiro. Parte dela fica presa na anterior por um tempo. Pular entre cinco coisas não é fazer cinco coisas: é fazer cinco coisas pela metade.\n\nPor isso o dia cheio de pequenas trocas cansa tanto e rende tão pouco.\n[[page]]\nNesta semana as sessões ficam mais longas, e a regra continua: uma tarefa só por sessão. Se lembrar de outra coisa no meio, anote num papel ao lado e volte. A anotação tira a coisa da cabeça sem tirar você da tarefa."},{"icon":"🎯","name":"Sessão de foco (60 min)","description":"60 minutos numa única tarefa importante, decidida antes. Celular em outro cômodo, notificações do computador desligadas, só as abas da tarefa abertas.","duration":60,"difficulty":3,"actionType":"Ação Recorrente","repetitions":2,"dias":[1,2],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":540,"preFlight":["Tarefa escrita antes de começar","Celular fora de alcance","Notificações desligadas","Só o que é da tarefa aberto"]},{"icon":"🎯","name":"Sessão de foco (75 min)","description":"75 minutos numa única tarefa importante, decidida antes. Celular em outro cômodo, notificações do computador desligadas, só as abas da tarefa abertas.","duration":75,"difficulty":3,"actionType":"Ação Recorrente","repetitions":3,"dias":[3,4,5],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":540,"preFlight":["Tarefa escrita antes de começar","Celular fora de alcance","Notificações desligadas","Só o que é da tarefa aberto"]},{"icon":"🔍","name":"Auditoria da sessão","description":"Na anotação: o que tentou interromper a sessão (de fora ou da sua cabeça) e quanto da sessão foi foco de verdade, de 0 a 10.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":5,"dias":[1,2,3,4,5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":615},{"icon":"📘","name":"Proteger a agenda","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Se o foco não tiver um lugar marcado na agenda, outras coisas ocupam o espaço: reuniões, pedidos, mensagens. Quem não protege o próprio tempo fica com as sobras.\n\nA solução é tratar a sessão de foco como um compromisso: marcada, com hora, e defendida como qualquer reunião importante.\n[[page]]\nHoje à tarde, você vai olhar a próxima semana e marcar os seus blocos de foco. Se trabalha com outras pessoas, avise que naquele horário você responde depois.\n\nO melhor horário costuma ser aquele em que você tem mais energia. Para muita gente, é de manhã, antes de abrir o e-mail."},{"icon":"🗓️","name":"Blocos de foco na semana","description":"Marque na sua agenda (e no planner) os blocos de foco da próxima semana, de preferência no seu melhor horário de energia.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1080},{"icon":"📘","name":"Tédio é treino","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Boa parte da dificuldade de focar não vem de fora: vem da vontade de fugir do tédio. No primeiro momento chato da tarefa, a mão vai sozinha para o celular.\n\nQuem nunca tolera um minuto de tédio — na fila, no elevador, no ônibus — treina o cérebro para fugir. E aí, na hora de focar, ele foge também.\n[[page]]\nUm treino simples fora das sessões: deixe de pegar o celular nos pequenos momentos de espera. Fique só esperando. É desconfortável no começo, e é exatamente esse desconforto que fortalece o foco."},{"icon":"🌇","name":"Encerrar o dia","description":"Revise o que ficou aberto, anote o próximo passo de cada coisa e escolha a tarefa da sessão de amanhã. Termine com \"dia encerrado\".","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"preFlight":["Pendências anotadas com próximo passo","Tarefa da sessão de amanhã escolhida","\"Dia encerrado\""]},{"icon":"🔁","name":"Revisão da semana 2","description":"Na anotação: a sessão mais longa que conseguiu manter, a nota média das auditorias e o projeto que vai usar no dia de 4 horas.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1125}]},{"level":3,"title":"Fase 3: Imersão","description":"Sessões de 90 minutos e o dia de 4 horas.","actions":[{"icon":"📘","name":"Sessões longas sem se esgotar","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[1],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Noventa minutos de foco é muito, e o cérebro precisa de pausas para manter o nível. A ideia não é aguentar no sofrimento, é trabalhar em ciclos.\n\nDepois de cada sessão longa, uma pausa de verdade: levantar, andar, olhar para longe, beber água. Sem celular, porque o celular não descansa a atenção, só troca o foco de lugar.\n[[page]]\nComer bem, dormir bem e não marcar sessões longas logo depois de uma refeição pesada também ajudam. O foco depende do corpo inteiro."},{"icon":"🎯","name":"Sessão de foco (90 min)","description":"90 minutos numa única tarefa importante, decidida antes. Celular em outro cômodo, notificações do computador desligadas, só as abas da tarefa abertas.","duration":90,"difficulty":3,"actionType":"Ação Recorrente","repetitions":4,"dias":[1,2,3,4],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":540,"preFlight":["Tarefa escrita antes de começar","Celular fora de alcance","Notificações desligadas","Só o que é da tarefa aberto"]},{"icon":"🔍","name":"Auditoria da sessão","description":"Na anotação: o que tentou interromper a sessão (de fora ou da sua cabeça) e quanto da sessão foi foco de verdade, de 0 a 10.","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":4,"dias":[1,2,3,4],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":630},{"icon":"📘","name":"Planejar o dia profundo","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[3],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"O dia de 4 horas de trabalho profundo é o fechamento da campanha. Para dar certo, ele precisa ser preparado como um evento: data marcada, projeto escolhido, agenda limpa.\n\nQuatro horas não precisam ser seguidas. Duas sessões de 90 minutos e uma de 60, com pausas, funcionam bem.\n[[page]]\nEscolha um projeto que mereça: algo importante que vem sendo adiado por precisar de tempo e cabeça. Defina antes o que seria um bom resultado no fim do dia.\n\nCancele ou remarque o que puder naquele dia, avise as pessoas e deixe tudo pronto na noite anterior."},{"icon":"🗺️","name":"Preparar o dia de 4 horas","description":"Escolha o projeto, defina o resultado esperado, limpe a agenda do dia seguinte e deixe tudo o que precisa já separado.","duration":30,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1080},{"icon":"📘","name":"Depois da campanha","description":"Leia a aula na aba Anotação e conclua no fim da leitura.","duration":15,"difficulty":1,"actionType":"Compromisso","repetitions":1,"dias":[5],"context":{"timeOfDay":"morning","energyLevel":"low"},"scheduledStartTime":480,"briefing":"Daqui a dois dias a campanha termina. O foco que você treinou se mantém com o mesmo remédio: sessões regulares, agenda protegida, ambiente preparado e o ritual de encerramento.\n\nNão precisa ser todo dia, nem 90 minutos sempre. Duas ou três sessões profundas por semana já colocam você bem à frente da maioria.\n[[page]]\nUma sugestão: transforme a sessão de foco e o encerramento do dia em ações suas no planner, nos dias e horários que funcionaram melhor nestas três semanas."},{"icon":"🌇","name":"Encerrar o dia","description":"Revise o que ficou aberto, anote o próximo passo de cada coisa e escolha a tarefa da sessão de amanhã. Termine com \"dia encerrado\".","duration":15,"difficulty":1,"actionType":"Ação Recorrente","repetitions":7,"dias":[1,2,3,4,5,6,7],"context":{"timeOfDay":"evening","energyLevel":"low"},"scheduledStartTime":1110,"preFlight":["Pendências anotadas com próximo passo","Tarefa da sessão de amanhã escolhida","\"Dia encerrado\""]},{"icon":"🏆","name":"Dia de trabalho profundo","description":"Quatro horas de trabalho profundo num projeto só (por exemplo, 90 + 90 + 60 minutos, com pausas). Na anotação, o que conseguiu fazer.","duration":240,"difficulty":3,"actionType":"Compromisso","repetitions":1,"dias":[6],"context":{"timeOfDay":"morning","energyLevel":"high"},"scheduledStartTime":510,"preFlight":["Projeto e resultado esperado definidos","Agenda limpa e pessoas avisadas","Celular e notificações fora durante as sessões","Pausas sem tela entre as sessões"]},{"icon":"🔁","name":"Revisão final","description":"Na anotação: como foi o dia de 4 horas, o que mudou no seu foco em três semanas e o que vai manter.","duration":15,"difficulty":2,"actionType":"Compromisso","repetitions":1,"dias":[7],"context":{"timeOfDay":"evening","energyLevel":"medium"},"scheduledStartTime":1125}]}]$modelo$::jsonb)
where id = '7f31c3d8-7a9a-4d4e-9b36-4f79a5f42a03';

update public.codex_catalog
set template = jsonb_set(template, '{levels,0,actions,0,briefing}', to_jsonb('Algumas pessoas falam pouco e todo mundo presta atenção. Outras falam muito e ninguém lembra do que disseram. A diferença quase nunca é a voz bonita ou o vocabulário. É clareza.

Quem é ouvido sabe o que quer dizer antes de abrir a boca. Quem não é, vai descobrindo enquanto fala: dá voltas, repete, explica o contexto do contexto, e quando chega ao ponto a atenção do outro já foi embora.
[[page]]
Três hábitos fazem alguém ser ouvido:

— Começar pelo ponto. Primeiro a conclusão ("acho que devemos adiar"), depois o porquê. Quem começa pelo porquê obriga o outro a adivinhar onde a conversa vai chegar.
— Uma ideia por vez. Três assuntos na mesma fala viram nenhum. Se são três, diga que são três e vá um por um.
— Parar quando terminou. O silêncio depois de uma frase clara tem mais força do que mais uma explicação.
[[page]]
A prática da próxima fase é simples: antes de uma conversa importante do dia, escreva o que quer dizer em duas frases. Se não couber em duas, você ainda não sabe o que quer dizer, e é melhor descobrir no papel do que na frente dos outros.

Não é para decorar. É para chegar na conversa sabendo onde ela termina.'::text))
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c07' and coalesce(template #>> '{levels,0,actions,0,briefing}', '') = '';

update public.codex_catalog
set template = jsonb_set(template, '{levels,0,actions,0,briefing}', to_jsonb('Esperar a inspiração é o jeito mais comum de não criar nada. Ela aparece de vez em quando, sem aviso, e quase nunca na hora em que dá para sentar e fazer.

Quem cria com frequência não espera. Senta num horário marcado, com um tempo curto, e começa mesmo sem vontade. A vontade costuma chegar depois dos primeiros minutos, não antes.
[[page]]
Prazo curto ajuda por um motivo simples: não dá tempo de julgar. Com duas horas pela frente, a cabeça gasta a primeira meia hora decidindo se a ideia é boa o bastante. Com quinze minutos, só dá para fazer.

Por isso a regra do sprint é produzir sem filtrar: escrever, rabiscar, listar, gravar. Apagar e escolher fica para depois. Uma sessão com dez ideias ruins e uma boa é uma sessão que funcionou.
[[page]]
Na próxima fase, todo dia: um problema criativo aberto (um texto, um nome, um desenho, uma solução), cronômetro em 15 minutos, e só parar quando ele tocar.

No fim, uma linha na anotação: o que saiu de mais interessante. É dessa lista que vem o material bom.'::text))
where id = '9f31c3d8-7a9a-4d4e-9b36-4f79a5f42c10' and coalesce(template #>> '{levels,0,actions,0,briefing}', '') = '';

commit;

-- CONFERENCIA (so le): nenhuma campanha com aula prometida e texto vazio.
select c.title, count(*) as aulas_vazias
from public.codex_catalog c,
     jsonb_array_elements(c.template -> 'levels') l,
     jsonb_array_elements(l -> 'actions') a
where coalesce(trim(a ->> 'briefing'), '') = '' and (a ->> 'description') ~* '^\s*leia (a|o) (aula|texto)'
group by c.title;
